INSERT INTO "ov_named" ("tbl", "row_no", "ref_id", "name") VALUES
  ('ov_dialog.bin', 100, 67175424, '我--抓--到--你--啦--'),
  ('ov_dialog.bin', 1000, 394068736, '看我的冰晶暗器！百发百中'),
  ('ov_dialog.bin', 1001, 394068992, '别说我不警告你，这是不对的'),
  ('ov_dialog.bin', 1002, 394069248, '红色果然运气不错，又赢了一场'),
  ('ov_dialog.bin', 1003, 394069504, '怎一个惨字了得~~'),
  ('ov_dialog.bin', 1004, 394133504, '看见我强壮的肌肉了吗？可不是摆设用的'),
  ('ov_dialog.bin', 1005, 394134272, '别动！吃我一斧'),
  ('ov_dialog.bin', 1006, 394134528, '老兄你力气太小啦！没感觉'),
  ('ov_dialog.bin', 1007, 394134784, '跟我道歉！让你说我矮了吗？'),
  ('ov_dialog.bin', 1008, 394135040, '兄弟姐妹们，永别了~'),
  ('ov_dialog.bin', 1009, 394199040, '不怕死的过来！大爷饿着呢'),
  ('ov_dialog.bin', 101, 67175680, '你--死--了--吗--'),
  ('ov_dialog.bin', 1010, 394199808, '我神出鬼没的本领你能奈我何？哈哈'),
  ('ov_dialog.bin', 1011, 394200064, '敢惹我？没看过我的真身吧'),
  ('ov_dialog.bin', 1012, 394200320, '真是没用，还想多玩会呢'),
  ('ov_dialog.bin', 1013, 394200576, '看来我这个吸血蝙蝠白当了~'),
  ('ov_dialog.bin', 1014, 394264576, '看见我的人都要死，我是恶魔'),
  ('ov_dialog.bin', 1015, 394265344, '对我来说只是雕虫小技，一下秒杀。'),
  ('ov_dialog.bin', 1016, 394265600, '你真是好大的胆子！来者何人？'),
  ('ov_dialog.bin', 1017, 394265856, '神总是不能挑战的，记住了！'),
  ('ov_dialog.bin', 1018, 394266112, '怎么可能？这是不可能发生的'),
  ('ov_dialog.bin', 1019, 394330112, '老老实实做个龟，通灵不是我本意'),
  ('ov_dialog.bin', 102, 67175936, '不甘心--我死也不甘心--'),
  ('ov_dialog.bin', 1020, 394330880, '龟也是有火的！'),
  ('ov_dialog.bin', 1021, 394331136, '不要打我，我帮你算命嘛'),
  ('ov_dialog.bin', 1022, 394331392, '我杀生了吗？阿弥陀佛~'),
  ('ov_dialog.bin', 1023, 394331648, '我不是死了，是成仙了'),
  ('ov_dialog.bin', 1024, 394395648, '我是冰中之王，看见我要下跪'),
  ('ov_dialog.bin', 1025, 394396416, '别说我欺负小的，是你先动手的'),
  ('ov_dialog.bin', 1026, 394396672, '就凭你？小子还嫩了点吧'),
  ('ov_dialog.bin', 1027, 394396928, '罪过啊，又消灭一个'),
  ('ov_dialog.bin', 1028, 394397184, '没人看见吧？丢人咯'),
  ('ov_dialog.bin', 1029, 394461184, '身体好重啊，走一步都不容易'),
  ('ov_dialog.bin', 103, 67305472, '打不过，闪！'),
  ('ov_dialog.bin', 1030, 394461952, '爆石阵！砸死了没'),
  ('ov_dialog.bin', 1031, 394462208, '不要打碎我的石头，好不容易长得'),
  ('ov_dialog.bin', 1032, 394462464, '混口饭吃不容易啊，收工'),
  ('ov_dialog.bin', 1033, 394462720, '这下可啥也不剩了'),
  ('ov_dialog.bin', 1034, 394526720, '小心小心，有没人看见我？'),
  ('ov_dialog.bin', 1035, 394527488, '给你365个飞镖！接招'),
  ('ov_dialog.bin', 1036, 394527744, '要跟我挑战吗？'),
  ('ov_dialog.bin', 1037, 394528000, '刺客的工作就是不知不觉地结束你'),
  ('ov_dialog.bin', 1038, 394528256, '杀人者人恒杀之阿~'),
  ('ov_dialog.bin', 1039, 394592256, '世间万物皆有其定律'),
  ('ov_dialog.bin', 104, 67305472, '我的我的都是我的！'),
  ('ov_dialog.bin', 1040, 394593024, '别怪我，你逼我的'),
  ('ov_dialog.bin', 1041, 394593280, '你伤害不了我的，还是收手吧'),
  ('ov_dialog.bin', 1042, 394593536, '求我吧，兴许我能救你一命呢'),
  ('ov_dialog.bin', 1043, 394593792, '也罢，这是命'),
  ('ov_dialog.bin', 1044, 394657792, '人在哪里？我最怕人了'),
  ('ov_dialog.bin', 1045, 394658560, '逃不了，我只好打了'),
  ('ov_dialog.bin', 1046, 394658816, '快逃快逃！人杀过来了'),
  ('ov_dialog.bin', 1047, 394659072, '死了？不是吧~'),
  ('ov_dialog.bin', 1048, 394659328, '死是一种解脱阿'),
  ('ov_dialog.bin', 1049, 394723328, '我飘，我飘，看看有多高'),
  ('ov_dialog.bin', 105, 67306240, '怎么样？怕了吧？'),
  ('ov_dialog.bin', 1050, 394724096, '给你个厉害的瞧瞧，没打中？'),
  ('ov_dialog.bin', 1051, 394724352, '打不中！哈哈'),
  ('ov_dialog.bin', 1052, 394724608, '呼！还好没事虚惊一场'),
  ('ov_dialog.bin', 1053, 394724864, '飘不起来了'),
  ('ov_dialog.bin', 1054, 394788864, '肚子好饿阿，没有又吃的阿？'),
  ('ov_dialog.bin', 1055, 394789632, '说都不听的，人家都说不打咯！'),
  ('ov_dialog.bin', 1056, 394789888, '等我吃饱了再打行不行啊？'),
  ('ov_dialog.bin', 1057, 394790144, '你看你看，叫你不要打还不行'),
  ('ov_dialog.bin', 1058, 394790400, '早知道肚子饿没力气的'),
  ('ov_dialog.bin', 1059, 394854400, '今天又出来找猎物啦'),
  ('ov_dialog.bin', 106, 67306496, '痛噢！'),
  ('ov_dialog.bin', 1060, 394855168, '蜇你没商量！看你细皮嫩肉的'),
  ('ov_dialog.bin', 1061, 394855424, '糟了，被暗算'),
  ('ov_dialog.bin', 1062, 394855680, '九泉之下安息吧，哈哈'),
  ('ov_dialog.bin', 1063, 394855936, '我的毒还没来的及使呢~'),
  ('ov_dialog.bin', 1064, 394919936, '我是百步穿杨，要不要瞧瞧？'),
  ('ov_dialog.bin', 1065, 394920704, '用石头都能砸死你'),
  ('ov_dialog.bin', 1066, 394920960, '兄弟们救命啊~我扛不住啦'),
  ('ov_dialog.bin', 1067, 394921216, '别看我瘦，骨头里是肌肉'),
  ('ov_dialog.bin', 1068, 394921472, '到地狱继续扔石头'),
  ('ov_dialog.bin', 1069, 394985472, '今天很郁闷，别来惹我'),
  ('ov_dialog.bin', 107, 67306752, '知道俺手上这对铜锤的厉害了吧？'),
  ('ov_dialog.bin', 1070, 394986240, '什么人？进来者死！'),
  ('ov_dialog.bin', 1071, 394986496, '好痛，快点住手'),
  ('ov_dialog.bin', 1072, 394986752, '总算出了口恶气'),
  ('ov_dialog.bin', 1073, 394987008, '怎么也得上天堂吧？'),
  ('ov_dialog.bin', 1074, 395051008, '我跟那些没用的东西不一样，很强的哦'),
  ('ov_dialog.bin', 1075, 395051776, '魔力附体，威力无穷！'),
  ('ov_dialog.bin', 1076, 395052032, '你给我挠痒痒吗？力气也太小了吧？'),
  ('ov_dialog.bin', 1077, 395052288, '下次叫小的对付你就行了'),
  ('ov_dialog.bin', 1078, 395052544, '天妒英才阿！'),
  ('ov_dialog.bin', 1079, 395116544, '我很丑但是我很温柔'),
  ('ov_dialog.bin', 108, 67307008, '一点也不好玩嘛！'),
  ('ov_dialog.bin', 1080, 395117312, '以牙还牙~'),
  ('ov_dialog.bin', 1081, 395117568, '我死了对你也没有好处的'),
  ('ov_dialog.bin', 1082, 395117824, '强壮的体魄是胜利的根本'),
  ('ov_dialog.bin', 1083, 395118080, '我死不瞑目阿~'),
  ('ov_dialog.bin', 1084, 395182080, '我曾经也美丽过，岁月不饶人啊'),
  ('ov_dialog.bin', 1085, 395182848, '一招，两招，三招'),
  ('ov_dialog.bin', 1086, 395183104, '你打不中我的，我没有实体'),
  ('ov_dialog.bin', 1087, 395183360, '我胜利了一百遍阿一百遍'),
  ('ov_dialog.bin', 1088, 395183616, '终于岁月又可以重来了'),
  ('ov_dialog.bin', 1089, 395247616, '我不喜欢阳光，喜欢黑暗的环境'),
  ('ov_dialog.bin', 109, 67371008, '不准踏进俺老牛的地盘！')
INSERT INTO "ov_named" ("tbl", "row_no", "ref_id", "name") VALUES
  ('ov_dialog.bin', 1090, 395248384, '天灵灵，地灵灵，牛鬼蛇神块显灵'),
  ('ov_dialog.bin', 1091, 395248640, '可不能不打招呼直接开仗'),
  ('ov_dialog.bin', 1092, 395248896, '我黑色的翅膀就是力量的象征'),
  ('ov_dialog.bin', 1093, 395249152, '作蝙蝠也要死~~'),
  ('ov_dialog.bin', 1094, 395313152, '斧头可是比石头还要厉害的武器'),
  ('ov_dialog.bin', 1095, 395313920, '小子，没看过斧头帮打人啊？'),
  ('ov_dialog.bin', 1096, 395314176, '看见我的大斧头还敢挑衅？'),
  ('ov_dialog.bin', 1097, 395314432, '一斧下去，干干净净'),
  ('ov_dialog.bin', 1098, 395314688, '个小还是吃亏'),
  ('ov_dialog.bin', 1099, 395378688, '平时要多运动，才能保持身材！'),
  ('ov_dialog.bin', 11, 65732608, '饿！我好饿！'),
  ('ov_dialog.bin', 110, 67371520, '俺老牛手正痒痒哪！'),
  ('ov_dialog.bin', 1100, 395379456, '看我一个脚趾头就可以踩扁你'),
  ('ov_dialog.bin', 1101, 395379712, '没看我皮厚吗?打我就是浪费力气'),
  ('ov_dialog.bin', 1102, 395379968, '易如反掌用在我身上最合适了~'),
  ('ov_dialog.bin', 1103, 395380224, '其实不想走，其实我想留'),
  ('ov_dialog.bin', 1104, 395444224, '想不到我原本只是一个很普通的石头吧？'),
  ('ov_dialog.bin', 1105, 395444992, '尝尝冤魂的力量哈'),
  ('ov_dialog.bin', 1106, 395445248, '你越打我，怨气就会散发的越多'),
  ('ov_dialog.bin', 1107, 395445504, '大功告成，吃饭去！'),
  ('ov_dialog.bin', 1108, 395445760, '啊呀啊呀！支持不住啦~'),
  ('ov_dialog.bin', 1109, 395509760, '谁要跟我比赛？谁能吃我一拳？'),
  ('ov_dialog.bin', 111, 67371776, '吃俺老牛一板斧！'),
  ('ov_dialog.bin', 1110, 395510528, '我左勾拳、右勾拳、问你怕没！'),
  ('ov_dialog.bin', 1111, 395510784, '拳法不错嘛！可惜较我还是差远了！'),
  ('ov_dialog.bin', 1112, 395511040, '一拳击毙！还有谁敢挑战我？哈哈'),
  ('ov_dialog.bin', 1113, 395511296, '死在战场，虽败犹荣！'),
  ('ov_dialog.bin', 1114, 395575296, '蓝色水晶意味着神奇、灵异'),
  ('ov_dialog.bin', 1115, 395576064, '把你封印起来，看你怎么办'),
  ('ov_dialog.bin', 1116, 395576320, '为什么不打其他的怪？~欺负人'),
  ('ov_dialog.bin', 1117, 395576576, '不是你死就是我亡，不好意思'),
  ('ov_dialog.bin', 1118, 395576832, '我化为一阵轻烟，随风而去~'),
  ('ov_dialog.bin', 1119, 395640832, '我不是孤魂野鬼，只是孤独的泡泡'),
  ('ov_dialog.bin', 112, 67372032, '敢打俺老牛？叫你吃不了兜着走！'),
  ('ov_dialog.bin', 1120, 395641600, '放个泡泡把你抱住，然后消灭你'),
  ('ov_dialog.bin', 1121, 395641856, '啊呀，泡泡被戳破了。'),
  ('ov_dialog.bin', 1122, 395642112, '跪下了？那也不好使！'),
  ('ov_dialog.bin', 1123, 395642368, '我悄悄地走了，不带走一个泡泡~'),
  ('ov_dialog.bin', 1124, 395706368, '我最喜欢吸人气了，越多越好'),
  ('ov_dialog.bin', 1125, 395707136, '暗黑之神奉我名降临！'),
  ('ov_dialog.bin', 1126, 395707392, '我是死神的使者，人的武器伤不了我'),
  ('ov_dialog.bin', 1127, 395707648, '又可以饱餐一顿了~'),
  ('ov_dialog.bin', 1128, 395707904, '你只是消灭了我的躯壳而已'),
  ('ov_dialog.bin', 1129, 395771904, '我的大钳子就能横扫千军！'),
  ('ov_dialog.bin', 113, 67372288, '嗬嗬！知道厉害了吧！'),
  ('ov_dialog.bin', 1130, 395772672, '速战速决！看钳~'),
  ('ov_dialog.bin', 1131, 395772928, '不知道昆虫是最强的生物吗？何况钢铁的'),
  ('ov_dialog.bin', 1132, 395773184, '让你平时踩虫子踩得这么过瘾！'),
  ('ov_dialog.bin', 1133, 395773440, '我还没娶老婆呢~~~~'),
  ('ov_dialog.bin', 1134, 395837440, '我是一条会飞的蛇，强悍阿！'),
  ('ov_dialog.bin', 1135, 395838208, '看我的金蛇缠丝手。'),
  ('ov_dialog.bin', 1136, 395838464, '妖也是有尊严的！凭什么说打就打？'),
  ('ov_dialog.bin', 1137, 395838720, '扑腾翅膀庆祝一下胜利'),
  ('ov_dialog.bin', 1138, 395838976, '下辈子我要做白娘子~'),
  ('ov_dialog.bin', 1139, 395902976, '拖着石锤到处溜达，多惬意啊'),
  ('ov_dialog.bin', 114, 67372544, '俺不相信俺会死！'),
  ('ov_dialog.bin', 1140, 395903744, '大爷教你几招，省得你丢人现眼'),
  ('ov_dialog.bin', 1141, 395904000, '妒嫉我生活质量高啊？'),
  ('ov_dialog.bin', 1142, 395904256, '清除了障碍，继续散布，啦啦啦'),
  ('ov_dialog.bin', 1143, 395904512, '呜呜~好厉害啊'),
  ('ov_dialog.bin', 1144, 395968512, '紫色水晶蕴含浪漫、姻缘'),
  ('ov_dialog.bin', 1145, 395969280, '插你的眼、封你的喉，再出必杀'),
  ('ov_dialog.bin', 1146, 395969536, '我惹不起我还躲不起吗？'),
  ('ov_dialog.bin', 1147, 395969792, '注定我们能够笑到最后的'),
  ('ov_dialog.bin', 1148, 395970048, '其他的兄弟要来帮我重生阿~'),
  ('ov_dialog.bin', 1149, 396034048, '我好想有个真实的躯体阿~'),
  ('ov_dialog.bin', 115, 67567616, '打狗不是好汉！'),
  ('ov_dialog.bin', 1150, 396034816, '掉入水魔炼狱去吧，很好玩的~'),
  ('ov_dialog.bin', 1151, 396035072, '水魔大神庇护我的元神吧！'),
  ('ov_dialog.bin', 1152, 396035328, '好久没大开杀戒了，过瘾阿~'),
  ('ov_dialog.bin', 1153, 396035584, '吾即追随大神的脚步'),
  ('ov_dialog.bin', 1154, 396099584, '好可怕啊！到处都是妖怪~'),
  ('ov_dialog.bin', 1155, 396100352, '讨厌！讨厌！你坏蛋~'),
  ('ov_dialog.bin', 1156, 396100608, '不要打！不要打！我投降~'),
  ('ov_dialog.bin', 1157, 396100864, '耶耶！原来我还挺厉害的，哈哈~'),
  ('ov_dialog.bin', 1158, 396101120, '晕！这么的就挂了？'),
  ('ov_dialog.bin', 1159, 396165120, '俗话都说龟长寿，我多大了？'),
  ('ov_dialog.bin', 116, 67567616, '哥们！俺来啦！'),
  ('ov_dialog.bin', 1160, 396165888, '龟急咬人！没听过？'),
  ('ov_dialog.bin', 1161, 396166144, '拼老命爬阿~后面打过来了'),
  ('ov_dialog.bin', 1162, 396166400, '看来我不是一般的乌龟~~'),
  ('ov_dialog.bin', 1163, 396166656, '还以为自己长生不老呢，被晃点了！'),
  ('ov_dialog.bin', 1164, 396230656, '好无聊！漂亮妹妹你要陪我玩吗？'),
  ('ov_dialog.bin', 1165, 396231424, '叔叔过来咯~等等我嘛'),
  ('ov_dialog.bin', 1166, 396231680, '问问而已，不用生气吧？'),
  ('ov_dialog.bin', 1167, 396231936, '嘻嘻，水当当的'),
  ('ov_dialog.bin', 1168, 396232192, '现在的小孩怎么这么强悍阿？'),
  ('ov_dialog.bin', 1169, 396296192, '我可是蝙蝠界的刘翔哦！'),
  ('ov_dialog.bin', 117, 67568384, '汪汪汪！汪汪汪！'),
  ('ov_dialog.bin', 1170, 396296960, '有眼不识泰山，该打！'),
  ('ov_dialog.bin', 1171, 396297216, '我没有害人啊，长得丑也有错？'),
  ('ov_dialog.bin', 1172, 396297472, '我还是有两把刷子的~'),
  ('ov_dialog.bin', 1173, 396297728, '丢人啊！怎么回去跟老大交待？'),
  ('ov_dialog.bin', 1174, 396361728, '想念以前阳光下的日子啊'),
  ('ov_dialog.bin', 1175, 396362496, '给你尝尝黑魔法的滋味'),
  ('ov_dialog.bin', 1176, 396362752, '老人家你也不放过？'),
  ('ov_dialog.bin', 1177, 396363008, '浓缩就是精华~懂不懂？'),
  ('ov_dialog.bin', 1178, 396363264, '轮回转世不要变猪~~'),
  ('ov_dialog.bin', 1179, 396427264, '我乃冰凌之王，统治着这片世界'),
  ('ov_dialog.bin', 118, 67568384, '快说,我埋这的骨头藏哪去了?')
INSERT INTO "ov_named" ("tbl", "row_no", "ref_id", "name") VALUES
  ('ov_dialog.bin', 1180, 396428032, '就你们几个？不够我练手的~'),
  ('ov_dialog.bin', 1181, 396428288, '哪里有蚊子在咬我？'),
  ('ov_dialog.bin', 1182, 396428544, '刚才不是很威风吗？'),
  ('ov_dialog.bin', 1183, 396428800, '果然江山辈有才人出阿~'),
  ('ov_dialog.bin', 1184, 396492800, '防御才是战斗的基础。'),
  ('ov_dialog.bin', 1185, 396493568, '要让你肠子都悔青咯，打我？'),
  ('ov_dialog.bin', 1186, 396493824, '我就让你打，看你能拿我怎么样？'),
  ('ov_dialog.bin', 1187, 396494080, '坚甲御敌，所向披靡'),
  ('ov_dialog.bin', 1188, 396494336, '我的外壳呢？'),
  ('ov_dialog.bin', 1189, 396558336, '憎恨人类，憎恨一切的生灵'),
  ('ov_dialog.bin', 119, 67568640, '我吐不出象牙的，别亲我'),
  ('ov_dialog.bin', 1190, 396559104, '不要跑！我杀！'),
  ('ov_dialog.bin', 1191, 396559360, '诅咒你，诅咒伤害我的人'),
  ('ov_dialog.bin', 1192, 396559616, '哈哈，全部都逃不出我的手掌心'),
  ('ov_dialog.bin', 1193, 396559872, '就算死了也还能继续作恶'),
  ('ov_dialog.bin', 1194, 396623872, '尽忠职守是我的天职'),
  ('ov_dialog.bin', 1195, 396624640, '你不进攻我就放你一马'),
  ('ov_dialog.bin', 1196, 396624896, '想攻破我的防御？没门'),
  ('ov_dialog.bin', 1197, 396625152, '非要人家使用暴力~没辙'),
  ('ov_dialog.bin', 1198, 396625408, '为国捐躯，死而无憾'),
  ('ov_dialog.bin', 1199, 396689408, '石头算什么东西，我轻易就可以弄碎'),
  ('ov_dialog.bin', 12, 65733120, '好家伙！'),
  ('ov_dialog.bin', 120, 67568640, '汪汪汪！汪汪汪！'),
  ('ov_dialog.bin', 1200, 396690176, '像碎石头一样把你脑袋碎了'),
  ('ov_dialog.bin', 1201, 396690432, '被打了！快点捡石头扔他'),
  ('ov_dialog.bin', 1202, 396690688, '举个白旗让大爷高兴高兴~'),
  ('ov_dialog.bin', 1203, 396690944, '做妖这么久，最失败这一次'),
  ('ov_dialog.bin', 1204, 396754944, '石头和我是近亲，只是他们太丑'),
  ('ov_dialog.bin', 1205, 396755712, '打你小人头，让你晕头走'),
  ('ov_dialog.bin', 1206, 396755968, '你再打我，我可要禁止你一切法术了'),
  ('ov_dialog.bin', 1207, 396756224, '我等有修养之物本不该如此计较'),
  ('ov_dialog.bin', 1208, 396756480, '我终于得到解脱了'),
  ('ov_dialog.bin', 1209, 396820480, '我刚睡着，又被吵醒了~'),
  ('ov_dialog.bin', 121, 67568896, '汪汪！好嘢！'),
  ('ov_dialog.bin', 1210, 396821248, '扰我清梦者该死！'),
  ('ov_dialog.bin', 1211, 396821504, '不想活得站出来，干脆点'),
  ('ov_dialog.bin', 1212, 396821760, '终于又可以回窝睡个好觉了'),
  ('ov_dialog.bin', 1213, 396822016, '搞什么啊？我要睡觉'),
  ('ov_dialog.bin', 1214, 396886016, '黄水晶暗示着好运、财富'),
  ('ov_dialog.bin', 1215, 396886784, '现在采用掘进战，靠近敌人'),
  ('ov_dialog.bin', 1216, 396887040, '坚决支持游击战，不断移动中'),
  ('ov_dialog.bin', 1217, 396887296, '我们取得全面的胜利！'),
  ('ov_dialog.bin', 1218, 396887552, '轻敌了，要吸取教训'),
  ('ov_dialog.bin', 1219, 396951552, '我要投胎，谁当我的替死鬼'),
  ('ov_dialog.bin', 122, 67569152, '兄弟们！替俺报仇啊！'),
  ('ov_dialog.bin', 1220, 396952320, '就是你了，当我替死鬼吧'),
  ('ov_dialog.bin', 1221, 396952576, '孤魂野鬼，百无禁忌'),
  ('ov_dialog.bin', 1222, 396952832, '总算是熬到头了，可以投胎了'),
  ('ov_dialog.bin', 1223, 396953088, '这下魂飞魄散了'),
  ('ov_dialog.bin', 1224, 397017088, '你看得我已不是一般的我'),
  ('ov_dialog.bin', 1225, 397017856, '我心不动而神动'),
  ('ov_dialog.bin', 1226, 397018112, '你攻击的我已不是现实的我'),
  ('ov_dialog.bin', 1227, 397018368, '除去世念，皈依无我'),
  ('ov_dialog.bin', 1228, 397018624, '我是一只信佛的石龙啊~'),
  ('ov_dialog.bin', 1229, 397082624, '龟兔赛跑，最后为什么龟赢？'),
  ('ov_dialog.bin', 123, 67633152, '只要有吃的啥都行！'),
  ('ov_dialog.bin', 1230, 397083392, '獠牙出动！'),
  ('ov_dialog.bin', 1231, 397083648, '啊呀~还好有甲，不然就见上帝了'),
  ('ov_dialog.bin', 1232, 397083904, '我跑步虽然慢，但绝对有毅力'),
  ('ov_dialog.bin', 1233, 397084160, '龟快的原因是抄近路！哈哈'),
  ('ov_dialog.bin', 1234, 397148160, '古老的怨灵聚集在我的身边'),
  ('ov_dialog.bin', 1235, 397148928, '冥顽不灵，我只好出手了'),
  ('ov_dialog.bin', 1236, 397149184, '人类，你不考虑一下后果吗？'),
  ('ov_dialog.bin', 1237, 397149440, '果然是条硬汉'),
  ('ov_dialog.bin', 1238, 397149696, '只求怨气能够散去'),
  ('ov_dialog.bin', 1239, 397213696, '小石魔要过河，咕噜一下滚下坡'),
  ('ov_dialog.bin', 124, 67633152, '有哥们受伤了！'),
  ('ov_dialog.bin', 1240, 397214464, '闭着双眼往前冲啊'),
  ('ov_dialog.bin', 1241, 397214720, '我躲，躲了一个是一个'),
  ('ov_dialog.bin', 1242, 397214976, '挂了几个？'),
  ('ov_dialog.bin', 1243, 397215232, '实力上的差距阿'),
  ('ov_dialog.bin', 1244, 397279232, '鲜红的颜色是我的特征，火一般的'),
  ('ov_dialog.bin', 1245, 397280000, '火焰求、火弹术、火圈术··'),
  ('ov_dialog.bin', 1246, 397280256, '不怕被我美丽的火焰烧到就开吧'),
  ('ov_dialog.bin', 1247, 397280512, '这是我们的红色旋风！'),
  ('ov_dialog.bin', 1248, 397280768, '红色将渐渐的弹去'),
  ('ov_dialog.bin', 1249, 397344768, '炸了炸了，头要炸了~'),
  ('ov_dialog.bin', 125, 67633920, '试试俺尖牙的厉害！'),
  ('ov_dialog.bin', 1250, 397345536, '这么坏，打你屁股！'),
  ('ov_dialog.bin', 1251, 397345792, '哈哈，不要挠我痒痒~'),
  ('ov_dialog.bin', 1252, 397346048, '敷咒的力量都用不上。'),
  ('ov_dialog.bin', 1253, 397346304, '我死了，咒语就会解开了~'),
  ('ov_dialog.bin', 1254, 397410304, '我一生孤苦飘零，居无定所。好可怜'),
  ('ov_dialog.bin', 1255, 397411072, '拿出幽都的看家本领，别给我丢人！'),
  ('ov_dialog.bin', 1256, 397411328, '小小的泡泡何害之有？'),
  ('ov_dialog.bin', 1257, 397411584, '集体飘走~~'),
  ('ov_dialog.bin', 1258, 397411840, '人生无常阿，谁知道下一秒在哪里~'),
  ('ov_dialog.bin', 1259, 397475840, '只在黑暗中飞行，没有看见过阳光'),
  ('ov_dialog.bin', 126, 67633920, '不要打我了，我才吃饱'),
  ('ov_dialog.bin', 1260, 397476608, '我是灵蝠，不想和你打~'),
  ('ov_dialog.bin', 1261, 397476864, '此刻雷达的作用还是很大的'),
  ('ov_dialog.bin', 1262, 397477120, '唉，实在情非得已。还好吧？'),
  ('ov_dialog.bin', 1263, 397477376, '即便枉死，我仍坚持我理想'),
  ('ov_dialog.bin', 1264, 397541376, '我们要和三眼人开战了！！'),
  ('ov_dialog.bin', 1265, 397542144, '既然是敌人就要毫不留情'),
  ('ov_dialog.bin', 1266, 397542400, '你是三眼人？卧底？无间道？'),
  ('ov_dialog.bin', 1267, 397542656, '回去领功！哈哈'),
  ('ov_dialog.bin', 1268, 397542912, '失策失策，没想到身高占这么多好处'),
  ('ov_dialog.bin', 1269, 397606912, '拿着大斧头呀，上山去砍柴呀。'),
  ('ov_dialog.bin', 127, 67634176, '好饿啊，谁来给我做午餐啊！')
INSERT INTO "ov_named" ("tbl", "row_no", "ref_id", "name") VALUES
  ('ov_dialog.bin', 1270, 397607680, '左一斧，右一斧···'),
  ('ov_dialog.bin', 1271, 397607936, '别以为长得比我高就不敢打你'),
  ('ov_dialog.bin', 1272, 397608192, '继续前进，上山砍柴'),
  ('ov_dialog.bin', 1273, 397608448, '我飞呀飞上天~'),
  ('ov_dialog.bin', 1274, 1969291264, '嘿，我听到你们的计划了，我要告诉别人。'),
  ('ov_dialog.bin', 1275, 1969291264, '王者争霸，天下第一！我就是见证人！'),
  ('ov_dialog.bin', 1276, 1969291264, '打我啊，我脸皮厚着呢，打不疼！'),
  ('ov_dialog.bin', 1277, 1969292288, '小子，有人在看着你呢，别让人失望啊。'),
  ('ov_dialog.bin', 1278, 1969292288, '让你打你还真打啊~打吧，谁打我最疼谁就最厉害�'),
  ('ov_dialog.bin', 128, 67634176, '哇哇哇！好疼！'),
  ('ov_dialog.bin', 129, 67634176, '想睡个好觉的不行'),
  ('ov_dialog.bin', 13, 65733376, '怕了吧？'),
  ('ov_dialog.bin', 130, 67634432, '赢啰赢啰！'),
  ('ov_dialog.bin', 131, 67634688, '死都死得这么帅!'),
  ('ov_dialog.bin', 132, 67634944, '好汉不吃眼前亏！'),
  ('ov_dialog.bin', 133, 67698688, '小怪也是有尊严的！'),
  ('ov_dialog.bin', 134, 67698688, '我最喜欢吃松子果了'),
  ('ov_dialog.bin', 135, 67698688, '兄弟们，一起上！'),
  ('ov_dialog.bin', 136, 67698688, '快溜！'),
  ('ov_dialog.bin', 137, 67699456, '咬你的鼻子!'),
  ('ov_dialog.bin', 138, 67699712, '我会生气的哦！'),
  ('ov_dialog.bin', 139, 67699968, '我可不是好欺负的！'),
  ('ov_dialog.bin', 14, 65733632, '好大胆！'),
  ('ov_dialog.bin', 140, 67700224, '不要啊！'),
  ('ov_dialog.bin', 141, 67829760, '我跳我跳我跳跳跳！'),
  ('ov_dialog.bin', 142, 67829760, '我救我救我救救救！'),
  ('ov_dialog.bin', 143, 67829760, '我逃我逃我逃逃逃！'),
  ('ov_dialog.bin', 144, 67830272, '我抓我抓我抓抓抓！'),
  ('ov_dialog.bin', 145, 67830528, '做鬼要厚道,行事要低调'),
  ('ov_dialog.bin', 146, 67830528, '我有个弟弟叫走肉！'),
  ('ov_dialog.bin', 147, 67831296, '我死啦！'),
  ('ov_dialog.bin', 148, 68222976, '欺负人家个子小！'),
  ('ov_dialog.bin', 149, 68222976, '保护庄稼是我的天职'),
  ('ov_dialog.bin', 15, 65733888, '遇上我算你倒霉！'),
  ('ov_dialog.bin', 150, 68222976, '有兄弟被人欺负啦！'),
  ('ov_dialog.bin', 151, 68222976, '来呀来呀，有本事就来打我呀'),
  ('ov_dialog.bin', 152, 68223744, '打不还手？那是笨蛋！'),
  ('ov_dialog.bin', 153, 68224000, '我什么时候才能变王子呀？'),
  ('ov_dialog.bin', 154, 68224000, '谁在找茬？'),
  ('ov_dialog.bin', 155, 68224256, '谁叫你找我打架的？活该！'),
  ('ov_dialog.bin', 156, 68224512, '哥们报仇，十年不晚！'),
  ('ov_dialog.bin', 157, 68288512, '陪我玩玩好不好？'),
  ('ov_dialog.bin', 158, 68289024, '有人陪我玩啦！'),
  ('ov_dialog.bin', 159, 68289280, '我轻轻地打你好不好？'),
  ('ov_dialog.bin', 16, 65734144, '好厉害！'),
  ('ov_dialog.bin', 160, 68289280, '就你这身子板我一刀砍俩'),
  ('ov_dialog.bin', 161, 68289792, '和人打架好好玩！'),
  ('ov_dialog.bin', 162, 68290048, '一点也不好玩嘛！'),
  ('ov_dialog.bin', 163, 68354048, '还是溜之大吉为妙！'),
  ('ov_dialog.bin', 164, 68354048, '大家并肩子上啊！'),
  ('ov_dialog.bin', 165, 68354048, '我爱那个香蕉，蕉蕉蕉蕉蕉蕉'),
  ('ov_dialog.bin', 166, 68354048, '我爱那个葡萄，萄萄萄萄萄萄'),
  ('ov_dialog.bin', 167, 68354048, '我爱那个苹果，果果果果果果'),
  ('ov_dialog.bin', 168, 68354816, '叽叽叽！叽叽叽！'),
  ('ov_dialog.bin', 169, 68355072, '我的屁股都被你打红了'),
  ('ov_dialog.bin', 17, 65863680, '叉叉！我喜欢叉叉！'),
  ('ov_dialog.bin', 170, 68355072, '哎哟！'),
  ('ov_dialog.bin', 171, 68355072, '让孙老大知道你欺负我,你就完了'),
  ('ov_dialog.bin', 172, 68355328, '嘢嘢！'),
  ('ov_dialog.bin', 173, 68355584, '岂有此理！'),
  ('ov_dialog.bin', 174, 68747264, '见过只会走路的鸟吗？'),
  ('ov_dialog.bin', 175, 68748032, '啄！啄！啄！'),
  ('ov_dialog.bin', 176, 68748288, '啄！啄！啄！'),
  ('ov_dialog.bin', 177, 68748544, '真菜！'),
  ('ov_dialog.bin', 178, 68748800, '手下留情啊！'),
  ('ov_dialog.bin', 179, 68749056, '要是会飞就好了！'),
  ('ov_dialog.bin', 18, 65864448, '喜欢我叉你哪儿？'),
  ('ov_dialog.bin', 180, 69468160, '保命要紧！'),
  ('ov_dialog.bin', 181, 69468160, '兔王就是我！神气吧？'),
  ('ov_dialog.bin', 182, 69468928, '面子要紧！'),
  ('ov_dialog.bin', 183, 69469184, '哎唷，还真疼！'),
  ('ov_dialog.bin', 184, 69469184, '打我可以，不要揪我耳朵'),
  ('ov_dialog.bin', 185, 69469440, '哼哼，知道我兔王的厉害了吧？'),
  ('ov_dialog.bin', 186, 69469696, '乖乖，好厉害！'),
  ('ov_dialog.bin', 187, 69599232, '是！主人！是！主人！'),
  ('ov_dialog.bin', 188, 69599744, '有人来啦－－'),
  ('ov_dialog.bin', 189, 69600000, '嘿！嘿！'),
  ('ov_dialog.bin', 19, 65864704, '有家伙打我！'),
  ('ov_dialog.bin', 190, 69600512, '嘿！嘿！'),
  ('ov_dialog.bin', 191, 69730304, '妖怪也有追求的！'),
  ('ov_dialog.bin', 192, 69731072, '看我的超级无敌叉！'),
  ('ov_dialog.bin', 193, 69731072, '头大魅力大，来来来，比比谁头大!!'),
  ('ov_dialog.bin', 194, 69731072, '谁说头大无脑'),
  ('ov_dialog.bin', 195, 69731328, '本妖很生气，后果很严重！'),
  ('ov_dialog.bin', 196, 69731328, '来比比谁的脑袋大'),
  ('ov_dialog.bin', 197, 69731584, '可怜的家伙!'),
  ('ov_dialog.bin', 198, 69731840, '好厉害！'),
  ('ov_dialog.bin', 199, 69795840, '我们地藏小妖最好客啦！'),
  ('ov_dialog.bin', 2, 65602560, '谁在打老人家我？'),
  ('ov_dialog.bin', 20, 65864960, '嘢！嘢！'),
  ('ov_dialog.bin', 200, 69795840, '妖兄弟们上啊！'),
  ('ov_dialog.bin', 201, 69796352, '欢迎来到我的领地！'),
  ('ov_dialog.bin', 202, 69796608, '十八层地狱很好玩的！'),
  ('ov_dialog.bin', 203, 69797120, '别以为我小就可以欺负我!'),
  ('ov_dialog.bin', 204, 69797376, '噢！'),
  ('ov_dialog.bin', 205, 69797632, '姥姥救命！'),
  ('ov_dialog.bin', 206, 70057984, '大怪这么多，我容易吗我！'),
  ('ov_dialog.bin', 207, 70058752, '你想打我？我又何尝不想叉你呢？'),
  ('ov_dialog.bin', 208, 70059008, '你想打我？我又何尝不想叉你呢？'),
  ('ov_dialog.bin', 209, 70059264, '后悔惹我了吧？')
INSERT INTO "ov_named" ("tbl", "row_no", "ref_id", "name") VALUES
  ('ov_dialog.bin', 21, 65865216, '饶命！'),
  ('ov_dialog.bin', 210, 70059520, '为什么受伤害的总是我？'),
  ('ov_dialog.bin', 211, 70059776, '妈呀！快逃！'),
  ('ov_dialog.bin', 212, 70123520, '怕不怕我？你到底怕不怕我？'),
  ('ov_dialog.bin', 213, 70124288, '气死我啦！'),
  ('ov_dialog.bin', 214, 70124544, '离开水也这么自在，阳光好温暖！'),
  ('ov_dialog.bin', 215, 70124800, '怕了吧？'),
  ('ov_dialog.bin', 216, 70125056, '我死不甘心！'),
  ('ov_dialog.bin', 217, 70125312, '快闪！'),
  ('ov_dialog.bin', 218, 70320128, '其实，俺不做老大已经很多年了！'),
  ('ov_dialog.bin', 219, 70320640, '来了个比我还肥的！'),
  ('ov_dialog.bin', 22, 65865472, '闪！'),
  ('ov_dialog.bin', 220, 70320896, '被俺老猪撞上，算你倒霉！'),
  ('ov_dialog.bin', 221, 70321152, '看不出挺厉害的嘛！'),
