  ('ov_dialog.bin', 446, 73925888, '哟嗬！嘢嘢！'),
  ('ov_dialog.bin', 447, 73926144, '人家这么可爱，你舍得吗？'),
  ('ov_dialog.bin', 448, 73990144, '我是快乐的小灯怪，飘来飘去真愉快！'),
  ('ov_dialog.bin', 449, 73990912, '嘿咻！嘿咻！'),
  ('ov_dialog.bin', 45, 66192640, '又有新鲜的人血喝啦！'),
  ('ov_dialog.bin', 450, 73991168, '哎唷！疼死我啦！'),
  ('ov_dialog.bin', 451, 73991424, '不要生我的气哦！'),
  ('ov_dialog.bin', 452, 73991680, '妈呀！'),
  ('ov_dialog.bin', 453, 74121216, '超级黑蜂强无敌！'),
  ('ov_dialog.bin', 454, 74121216, '偶来啦！'),
  ('ov_dialog.bin', 455, 74121216, '蛰遍天下无敌手！'),
  ('ov_dialog.bin', 456, 74121728, '有人来啦，冲啊！'),
  ('ov_dialog.bin', 457, 74121984, '蛰你脖子！蛰你屁股！'),
  ('ov_dialog.bin', 458, 74122240, '捅了黑蜂窝,你麻烦大了!'),
  ('ov_dialog.bin', 459, 74122496, '超级黑蜂强无敌！'),
  ('ov_dialog.bin', 46, 66192896, '好家伙！'),
  ('ov_dialog.bin', 460, 74122752, '兄弟们，救我！'),
  ('ov_dialog.bin', 461, 74186752, '为什么周围有这么多叫做人的家伙？'),
  ('ov_dialog.bin', 462, 74187520, '我好像没有惹你哦！'),
  ('ov_dialog.bin', 463, 74187776, '肥肥地身躯，小小地脸，慢慢地爬行钻树眼。'),
  ('ov_dialog.bin', 464, 74187776, '又有好吃的送上门来了'),
  ('ov_dialog.bin', 465, 74188032, '不要小瞧哦哦！'),
  ('ov_dialog.bin', 466, 74188288, '为什么受伤的总是我？'),
  ('ov_dialog.bin', 467, 74252288, '牛皮不是吹的！'),
  ('ov_dialog.bin', 468, 74252288, '敢欺负俺牛头面具的兄弟！'),
  ('ov_dialog.bin', 469, 74253056, '我顶！我顶！'),
  ('ov_dialog.bin', 47, 66256896, '我是刑天我怕谁！'),
  ('ov_dialog.bin', 470, 74253312, '我顶！我顶！'),
  ('ov_dialog.bin', 471, 74253568, '牛皮不是吹的！'),
  ('ov_dialog.bin', 472, 74253824, '不是来真的吧？'),
  ('ov_dialog.bin', 473, 74317824, '想尝尝俺鹿角的厉害吗？'),
  ('ov_dialog.bin', 474, 74317824, '兄弟有麻烦！'),
  ('ov_dialog.bin', 475, 74318592, '小鹿撞撞！'),
