  ('ov_dialog.bin', 479, 74383360, '敢欺负我们姐妹？活得不耐烦啦？'),
  ('ov_dialog.bin', 48, 66257408, '我是刑天我怕谁！')
INSERT INTO "ov_named" ("tbl", "row_no", "ref_id", "name") VALUES
  ('ov_dialog.bin', 480, 74383360, '想看我的脸吗？嘻嘻，就不给你看！'),
  ('ov_dialog.bin', 481, 74384128, '呀呀！呀呀！'),
  ('ov_dialog.bin', 482, 74384384, '呀呀！呀呀！'),
  ('ov_dialog.bin', 483, 74384640, '哟嚯！姐妹们，我赢啦！'),
  ('ov_dialog.bin', 484, 74384896, '丢脸死啦！'),
  ('ov_dialog.bin', 485, 74448896, '我们面具家族，可是有组织有纪律的！'),
  ('ov_dialog.bin', 486, 74449408, '好像有危险！'),
  ('ov_dialog.bin', 487, 74449664, '不准欺负我的面具孩儿们！'),
  ('ov_dialog.bin', 488, 74449920, '我这张帅脸，不是谁都可以看的'),
  ('ov_dialog.bin', 489, 74450176, '现在的人也越来越不经打了！'),
  ('ov_dialog.bin', 49, 66257664, '看我的左勾拳！看我的右勾拳！'),
  ('ov_dialog.bin', 490, 74450432, '孩儿们替我报仇！'),
  ('ov_dialog.bin', 491, 74514432, '见过我兄弟吗？它是小小蜗牛怪……'),
  ('ov_dialog.bin', 492, 74515200, '试试我们蜗牛兄弟的厉害！'),
  ('ov_dialog.bin', 493, 74515456, '别人都说我很有内涵'),
  ('ov_dialog.bin', 494, 74515456, '看你的招厉害还是我的壳硬'),
  ('ov_dialog.bin', 495, 74515712, '再来打过！'),
  ('ov_dialog.bin', 496, 74515968, '哎唷！'),
  ('ov_dialog.bin', 497, 74579968, '小小蜗牛怪，越看越可爱，嘻嘻…'),
  ('ov_dialog.bin', 498, 74580736, '先热热身吧！'),
  ('ov_dialog.bin', 499, 74580736, '别打我，我是路过的'),
  ('ov_dialog.bin', 5, 65667072, '嫩嫩的人肉最养颜啦！'),
  ('ov_dialog.bin', 50, 66257920, '拜托，用点劲儿好不好？'),
  ('ov_dialog.bin', 500, 74580992, '啦啦啦，我走到哪里都有家'),
  ('ov_dialog.bin', 501, 74580992, '哎哟！'),
  ('ov_dialog.bin', 502, 74581248, '看我超强必杀！嘿嘿！'),
  ('ov_dialog.bin', 503, 74581504, '噢！'),
  ('ov_dialog.bin', 504, 74645504, '俺大熊可不是好惹的哦！'),
  ('ov_dialog.bin', 505, 74646272, '吼吼，想吃我一记熊掌吗？'),
  ('ov_dialog.bin', 506, 74646528, '吼吼，想吃我一记熊掌吗？'),
  ('ov_dialog.bin', 507, 74646784, '熊掌的味道如何，吼吼？'),
  ('ov_dialog.bin', 508, 74647040, '我可不想变成红烧熊掌！'),
  ('ov_dialog.bin', 509, 74711808, '哼!我可是吃肉的'),
  ('ov_dialog.bin', 51, 66258176, '不怕死的就上！'),
  ('ov_dialog.bin', 510, 74712064, '小心我咬你哦!'),
  ('ov_dialog.bin', 511, 74776576, '本鸟一般不和人说话的……'),
  ('ov_dialog.bin', 512, 74777088, '我好像看到了人！'),
  ('ov_dialog.bin', 513, 74777344, '好家伙！'),
  ('ov_dialog.bin', 514, 74777600, '好家伙！'),
  ('ov_dialog.bin', 515, 74777856, '神鸟可不是吹的！'),
  ('ov_dialog.bin', 516, 74778112, '不会吧？'),
  ('ov_dialog.bin', 517, 74842112, '乖乖的，乖乖的……'),
  ('ov_dialog.bin', 518, 74843136, '欺负我不会动，小心我妈妈收拾你'),
  ('ov_dialog.bin', 519, 74843136, '不要打我好不好？'),
  ('ov_dialog.bin', 52, 66258432, '终于来了个厉害的！'),
  ('ov_dialog.bin', 520, 74907648, '我在天上飞呀，看我的小叉叉呀！'),
  ('ov_dialog.bin', 521, 74908160, '唷！唷！有人来喽！'),
  ('ov_dialog.bin', 522, 74908416, '看我的叉叉！'),
  ('ov_dialog.bin', 523, 74908416, '我这身行头蛮帅'),
  ('ov_dialog.bin', 524, 74908672, '狗急了跳墙，猪急了能上树'),
  ('ov_dialog.bin', 525, 74908928, '唷！唷！太棒啦！'),
  ('ov_dialog.bin', 526, 74909184, '见鬼啰！'),
  ('ov_dialog.bin', 527, 74973184, '像我这样的天才猴子你见过吗？'),
