  ('ov_dialog.bin', 534, 75039488, '呼呼！呼呼！'),
  ('ov_dialog.bin', 535, 75039744, '呼呼！呼呼！'),
  ('ov_dialog.bin', 536, 75040000, '精灵不是随便惹的！'),
  ('ov_dialog.bin', 537, 75040256, '下次再来打过！'),
  ('ov_dialog.bin', 538, 75104256, '打你，是因为我喜欢你，咯咯！'),
  ('ov_dialog.bin', 539, 75105024, '疼不疼啊？真让人心疼啊！'),
  ('ov_dialog.bin', 54, 66388736, '嘿咻！嘿咻！'),
  ('ov_dialog.bin', 540, 75105280, '哎唷！'),
  ('ov_dialog.bin', 541, 75105536, '打死你，是因为我喜欢死你啦，咯咯！'),
  ('ov_dialog.bin', 542, 75105792, '你舍得我死么？'),
