INSERT INTO "ov_named" ("tbl", "row_no", "ref_id", "name") VALUES
  ('ov_dialog.bin', 570, 75498496, '又来惹我？'),
  ('ov_dialog.bin', 571, 75498752, '何苦来惹我？'),
