  ('ov_dialog.bin', 573, 75563008, '真饿啊……'),
  ('ov_dialog.bin', 574, 75563520, '又有大餐送上门啦！'),
  ('ov_dialog.bin', 575, 75563520, '其实我是只羊'),
  ('ov_dialog.bin', 576, 75563776, '我的口水都流出来啦！'),
  ('ov_dialog.bin', 577, 75564032, '挺厉害的嘛'),
  ('ov_dialog.bin', 578, 75564288, '我的口水都流出来啦！'),
  ('ov_dialog.bin', 579, 75564544, '噢－－'),
  ('ov_dialog.bin', 58, 66389504, '我还不想死呢，呜呜呜……'),
  ('ov_dialog.bin', 580, 75628544, '陪我玩玩好不好？'),
