  ('ov_dialog.bin', 584, 75629824, '和人打架好好玩！'),
  ('ov_dialog.bin', 585, 75630080, '一点也不好玩嘛！'),
  ('ov_dialog.bin', 586, 76087296, '小心哦！我过来了哦！'),
