  ('ov_dialog.bin', 595, 76153600, '唉！又逼小妖我出手！'),
  ('ov_dialog.bin', 596, 76153856, '欺负我头上没长毛么？'),
  ('ov_dialog.bin', 597, 76154112, '记得将这里打扫干净哦！'),
  ('ov_dialog.bin', 598, 76154368, '糟糕！又弄脏啦！'),
  ('ov_dialog.bin', 599, 76218368, '越是虚幻的越美丽，越是美丽的越伤人！'),
  ('ov_dialog.bin', 6, 65667584, '过来呀，小乖乖！'),
  ('ov_dialog.bin', 60, 66453504, '肚子又饿了……'),
  ('ov_dialog.bin', 600, 76218368, '谁那么狠心，伤害我的同伴？'),
  ('ov_dialog.bin', 601, 76218880, '遇见我是你美丽的错误！'),
  ('ov_dialog.bin', 602, 76219136, '没听过越是美丽的越伤人吗？咯咯！'),
  ('ov_dialog.bin', 603, 76219392, '我这么美丽，你忍心么？'),
  ('ov_dialog.bin', 604, 76219648, '别伤心哦，死在我手上是你美丽的宿命！'),
  ('ov_dialog.bin', 605, 76219904, '死亡也是一场幻觉！'),
  ('ov_dialog.bin', 606, 76283904, '啷里个啷～啷里个啷～'),
  ('ov_dialog.bin', 607, 76283904, '哥们并肩子上啊！'),
  ('ov_dialog.bin', 608, 76284416, '俺好像闻到了血的鲜味！啧啧！'),
  ('ov_dialog.bin', 609, 76284672, '新鲜人血的滋味真不错！啧啧！'),
  ('ov_dialog.bin', 61, 66454016, '有肥羊入口啦！'),
  ('ov_dialog.bin', 610, 76284928, '哎唷妈呀！'),
  ('ov_dialog.bin', 611, 76285184, '俺吸血霸王蚊的名头可不是白叫的！'),
  ('ov_dialog.bin', 612, 76285440, '这下亏大啦！'),
  ('ov_dialog.bin', 613, 76349440, '三兄弟中我最牛！不信你试试？'),
  ('ov_dialog.bin', 614, 76349952, '不要害怕哦！别跑哦！'),
  ('ov_dialog.bin', 615, 76350208, '不要害怕哦！别跑哦！'),
  ('ov_dialog.bin', 616, 76350464, '还好我有壳！'),
  ('ov_dialog.bin', 617, 76350720, '嘻嘻，原来比我还肉！'),
  ('ov_dialog.bin', 618, 76350976, '这下面子丢大啦！'),
  ('ov_dialog.bin', 619, 76414976, '我得意的笑～～我得意的笑～～'),
  ('ov_dialog.bin', 62, 66454272, '这家伙挺肥的，不错不错！'),
  ('ov_dialog.bin', 620, 76415488, '过来呀，小乖乖，陪我玩玩儿～'),
  ('ov_dialog.bin', 621, 76415744, '好玩吗？'),
