  ('ov_help.bin', 97, 98, '社会属性'),
  ('ov_help.bin', 98, 99, '念力和耐力'),
  ('ov_hint.bin', 0, 65537, '在/C05龙城守城卫兵阿蒙/C00处接到委托：去/C05听溪走廊、缘溪走廊或阳泉平原/C00消灭/C10甲虫/C00，并收集/C0410只硬壳/C00。'),
  ('ov_hint.bin', 1, 65538, '收集/C0410只硬壳/C00，交给守城卫兵阿蒙，任务完成。'),
  ('ov_hint.bin', 10, 262149, '将蛇胆酒送给木匠左异。'),
  ('ov_hint.bin', 100, 2359297, '在桃源和听溪走廊杀小食人花和食人花，收集个花瓣和个带牙的花瓣。/C05/C00/C10/C00/C0415/C00/C046/C00'),
  ('ov_hint.bin', 101, 2424833, '在/C05阳泉平原上和阳泉平原左/C00杀死/C10食人花20朵/C00。'),
  ('ov_hint.bin', 102, 2490369, '前往/C05幻想矿洞/C00挖/C043个废铜烂铁/C00给守城卫兵阿森。'),
  ('ov_hint.bin', 103, 2555905, '学习如何钓鱼，满足条件后，亲自钓/C041条小鱼/C00送给守城卫兵阿森。'),
  ('ov_hint.bin', 104, 2621441, '前往/C05龙城南郊或北郊/C00杀/C0410个火鸟蛋/C00，同时收集/C04树枝15个/C00，交给/C05守城卫兵阿卡/C00。'),
  ('ov_hint.bin', 105, 2686977, '前往/C05龙城北郊/C00打桃树妖收集/C04桃叶20个/C00，交给/C05守城卫兵阿卡/C00。'),
  ('ov_hint.bin', 106, 2752513, '前往/C05龙城北郊/C00收集/C04桃叶5个、花瓣5个、带牙的花瓣5个、树枝5个、蛋壳5个/C00，交给/C05守城卫兵阿卡/C00。'),
  ('ov_hint.bin', 107, 2818049, '前往/C05龙城西郊/C00打海龟，收集/C048个完整的龟板/C00和/C0412个残缺的龟板/C00，交给/C05守城卫兵阿堂/C00。'),
  ('ov_hint.bin', 108, 2883585, '前往/C05龙城西郊/C00打木头人，收集/C0418个木头零件/C00，交给/C05守城卫兵阿堂/C00。'),
  ('ov_hint.bin', 109, 2949121, '前往/C05龙城南郊/C00杀/C1010只白兔/C00和/C1030个树妖/C00，这个任务需要有无比的耐心和努力，加油哦！'),
  ('ov_hint.bin', 11, 262150, '将蛇胆酒送给矿工沙良。'),
  ('ov_hint.bin', 110, 3014657, '前往/C05龙城西郊/C00收服/C1030个鬼火/C00，让它们得到安息。'),
  ('ov_hint.bin', 111, 3080193, '前往/C05龙城西郊/C00打败/C1025个鬼火和15个木头人/C00，看看灵魂燃烧的方式。'),
  ('ov_hint.bin', 112, 3145729, '前往/C05上古岳平原/C00教训吵闹不休的/C10绿蛙兵20只和夭夭15只/C00。'),
  ('ov_hint.bin', 113, 3211265, '做一剂药需要/C0412根黄蜂刺和9张蛙皮/C00，可以在/C10黄蜂和绿蛙兵/C00的身上获得。'),
  ('ov_hint.bin', 114, 3276801, '前往/C05仙踪森林和龙城东郊/C00收集/C0420根大黄蜂刺和15个蛾蛹黏液，大黄蜂会掉大黄蜂刺，蛾蛹怪会掉蛾蛹黏液。'),
  ('ov_hint.bin', 115, 3342337, '从龙城西郊、经过碧野岭前往仙踪森林，在那里消灭条赤蛇和条碧蛇。/C05/C00/C1020/C00/C1015/C00'),
  ('ov_hint.bin', 116, 3407873, '出长乐村，经过阳泉平原右前往/C05陶陶洞/C00，清剿/C10机关兔30个/C00和/C10小小傀儡怪20个/C00。建议组队前往。'),
  ('ov_hint.bin', 117, 3473409, '穿过龙城东郊，在/C05一叶岭/C00有许多/C10地藏小妖/C00游荡，收集它们身手掉落的/C04地藏宝珠18个/C00，交给小徒清心。'),
  ('ov_hint.bin', 118, 3538945, '从龙城东郊经寻仙道到/C05华山脚/C00，打败/C10山狼20只/C00，同时消灭/C05千叶森林/C00的/C10灰狼20只/C00。'),
  ('ov_hint.bin', 119, 3604481, '从龙城西郊往西南走，找到/C05黄鹤遗址/C00，在遗址里收集/C0420个破损的木箱锁/C00，并清除/C10轮面怪20个/C00。请组队前往。'),
  ('ov_hint.bin', 12, 262151, '将蛇胆酒送给传令官莫贤。'),
  ('ov_hint.bin', 120, 3670017, '前往/C05黄鹤遗址/C00，消灭里面的/C10铁钳人30个/C00。另外还需要消灭/C05千叶森林/C00的/C10黑蜂25只/C00。'),
  ('ov_hint.bin', 121, 3735553, '小徒明月请你探察西北方的/C05源源洞/C00，清除洞内的/C10尖嘴鼠30只/C00和/C10小虱子20只/C00。建议组队前往。'),
  ('ov_hint.bin', 122, 3801089, '前往/C05黄鹤遗址/C00，消灭/C1030个傀儡怪/C00。再到/C05华山脚/C00附近或者/C05仙踪森林/C00，收集/C0430个灵蛇蜒/C00。'),
  ('ov_hint.bin', 123, 3866625, '从龙城东郊、经一叶岭到/C05千叶森林/C00，那边的/C10飞天小猴/C00身上会掉落/C04飞猴翅/C00，请帮忙打/C0420个/C00吧。'),
  ('ov_hint.bin', 124, 3932161, '帮小徒明月到/C05华山地宫和黄鹤遗址/C00清除/C10机关器、烛台怪、齿轮机关人和地翼魔/C00各/C1010只/C00。'),
  ('ov_hint.bin', 125, 3997697, '到/C05黄鹤遗址第四层/C00消灭/C1020只地翼魔/C00；到/C05华山地宫第三层/C00打败/C1020只独角兽/C00，证明自己的能力。'),
  ('ov_hint.bin', 126, 4063233, '到出云城外打/C10黄鱼怪/C00和/C10蓝鱼怪/C00各/C1030只/C00，回来找阿歧老爹。'),
  ('ov_hint.bin', 127, 4128769, '到/C05出云山道/C00消灭/C1020只玄武兽/C00，再去/C05大秦山原东/C00消灭/C1030只苍狼/C00，回来找阿歧老爹听故事。'),
  ('ov_hint.bin', 128, 4194305, '从大秦山西经落霞坡，可进入/C05幻萤谷/C00。谷中盘踞着很多/C10碧磷毒蛇和赤焰毒蛇/C00，请你各驱赶/C1030条/C00。'),
  ('ov_hint.bin', 129, 4259841, '去/C05大秦山原/C00杀/C1020只苍狼皇/C00，再去打/C10大熊/C00，收集大熊身上掉落的/C10熊掌10个/C00。'),
  ('ov_hint.bin', 13, 262152, '回到店小二阿晃处领取报酬，任务完成。'),
  ('ov_hint.bin', 130, 4325377, '去找/C05飞空艇小姐云淇/C00请她帮忙。'),
  ('ov_hint.bin', 131, 4390913, '帮指导员天晴带话给治疗NPC/C05妙仙儿/C00。'),
  ('ov_hint.bin', 132, 4456449, '尝试与人组队，成功后回去找指导员天衣。'),
  ('ov_hint.bin', 133, 4521985, '帮指导员天衣带话给/C05桃树仙/C00。'),
  ('ov_hint.bin', 134, 4587521, '帮指导员天真买/C05一瓶豆奶/C00。'),
  ('ov_hint.bin', 135, 4653057, '帮指导员天真带话给/C05仓库管理员暖暖/C00。'),
  ('ov_hint.bin', 136, 4718593, '去找/C05飞空艇小姐千鹤/C00请她帮忙。'),
  ('ov_hint.bin', 137, 4784129, '帮指导员柳飘带话给治疗NPC/C05真纱/C00。'),
  ('ov_hint.bin', 138, 4849665, '尝试与人组队，成功后回去找指导员柳溪。'),
  ('ov_hint.bin', 139, 4915201, '帮指导员柳溪带话给/C05柳树仙/C00。'),
  ('ov_hint.bin', 14, 327681, '帮龙城观音院的/C05小和尚正中/C00夺回被/C10狐妖/C00抢走的/C04翡青念珠/C00。狐妖通常在/C05龙城东郊、寻仙道/C00一带出没。'),
  ('ov_hint.bin', 140, 4980737, '帮指导员柳丝买/C05一瓶豆奶/C00。'),
  ('ov_hint.bin', 141, 5046273, '帮指导员柳丝带话给/C05仓库管理员百合/C00。'),
  ('ov_hint.bin', 142, 5111809, '帮龙城/C05守城卫兵阿炎/C00寻找/C04玛瑙/C00，传说玛瑙由/C05华山地宫/C00里的/C04独角兽/C00的血凝结而成。'),
  ('ov_hint.bin', 143, 5111810, '要将玛瑙打造成玛瑙戒指，需要找/C04龙城天道山分店/C00。'),
  ('ov_hint.bin', 144, 5111811, '将玛瑙交给龙城天道山分店，得到打造好的玛瑙戒指。'),
  ('ov_hint.bin', 145, 5111812, '将玛瑙戒指交给守城卫兵阿炎，他托你带个口信给他妻子阿筝。阿炎的家在北城门附近。'),
  ('ov_hint.bin', 146, 5111813, '阿筝收到口信后，约定七夕那天与阿炎不见不散。'),
  ('ov_hint.bin', 147, 5111814, '向阿炎转述阿筝的约定，任务完成。'),
  ('ov_hint.bin', 148, 5177345, '帮/C05桃源村小松/C00采集/C0410片初生的桃叶/C00，/C05桃源/C00的/C10小夭夭/C00身上会掉初生的桃叶。'),
  ('ov_hint.bin', 149, 5177346, '将10片初生的桃叶交给小松，得到一个/C04花篮/C00，帮小松把花篮送给小松的姐姐/C05伊源/C00。'),
  ('ov_hint.bin', 15, 327682, '一打狐妖，得到假的翡青念珠。'),
  ('ov_hint.bin', 150, 5177347, '将10片初生的桃叶交给小松，任务完成。'),
  ('ov_hint.bin', 151, 5177348, '将花篮送给小松的姐姐伊源，任务完成。'),
  ('ov_hint.bin', 152, 5242881, '帮助/C04桃源村伊源/C00完成丝帕上的题诗。'),
  ('ov_hint.bin', 153, 5242882, '骑上小火鸟，将/C04丝帕/C00送给/C05长乐村药衡/C00。/C05飞空艇仙子云淇/C00会免费将你传送过去。/C04限时30分钟/C00。'),
  ('ov_hint.bin', 154, 5242883, '将伊源的丝帕交给药衡，药衡请你回送一瓶/C04白雪珍珠羹/C00给伊源。'),
  ('ov_hint.bin', 155, 5308417, '帮长乐村/C05拓老爹/C00找/C05茶姥/C00要一贴驱除风寒的/C04药膏/C00来，在小地图里可以查看到茶姥的位置。')
INSERT INTO "ov_named" ("tbl", "row_no", "ref_id", "name") VALUES
  ('ov_hint.bin', 156, 5308418, '去/C05阳泉平原中/C00收集/C0410个/C10猫妖/C00的/C04灵妖猫爪/C00，交给茶姥。'),
  ('ov_hint.bin', 157, 5308419, '合成药膏还需要/C04空瓶子/C00，在/C05道具商人杜若/C00那里可以买到。'),
  ('ov_hint.bin', 158, 5308420, '收集齐所有材料交给茶姥，合成出/C04药膏/C00，给/C05拓老爹/C00送去。'),
  ('ov_hint.bin', 159, 5373953, '接受龙城/C05小米/C00的考验，回答他的问题。'),
  ('ov_hint.bin', 16, 327683, '二打狐妖，得到假的翡青念珠。'),
  ('ov_hint.bin', 160, 5439489, '帮龙城/C05广成子/C00收集炼制丹药所需的材料：/C04山鼠尾巴、黑蜂翅膀、狼皮/C00。'),
  ('ov_hint.bin', 161, 5505025, '接受/C05哈大娘/C00托付，找/C05治疗师妙仙子/C00收集/C04玲珑草、无颜花和寂寞果/C00，妙仙子就在村中间的桃树屋附近。'),
  ('ov_hint.bin', 162, 5505026, '在治疗师妙仙子处得到玲珑草、无颜花和寂寞果，回去交给/C05哈大娘/C00。'),
  ('ov_hint.bin', 163, 5505027, '合成药品还需要/C04空瓶子/C00，在/C05道具商人清悠/C00那里可以买到。'),
  ('ov_hint.bin', 164, 5505028, '收集齐所有材料交给哈大娘，合成出/C04哈氏金创药/C00，给/C05壶公/C00送去。'),
  ('ov_hint.bin', 165, 5505029, '将哈氏金创药交给壶公，任务完成。'),
  ('ov_hint.bin', 166, 5570561, '看见旁边那个/C04红色旋转的光环/C00了吗？那是通往/C05芳草林/C00的传送点，走过去，踩在光环上就可以去到芳草林了！'),
  ('ov_hint.bin', 167, 5570562, '那里有许多1级的/C10粉粉兔/C00，/C04左键单击/C00就可以进行攻击，如果你能够连续打败/C045只/C00粉粉兔，就可通过考验。'),
  ('ov_hint.bin', 168, 5570563, '通过考验后，去村子中间找/C05指引仙子天晴/C00，她会教你学习第一个技能。'),
  ('ov_hint.bin', 169, 5570564, '恭喜你连续击败5只粉粉兔，顺利通过了第一个考验，现在可以去村子中间找/C05指引仙子天晴/C00，她会教你学习新手技能。'),
  ('ov_hint.bin', 17, 327684, '三打狐妖，得到真的翡青念珠，交还给小和尚正中，任务完成。'),
  ('ov_hint.bin', 170, 5636097, '去长乐村以北的/C05阳泉平原/C00，在/C10小野猪/C00身上收集/C042只野猪牙/C00，帮桃源村/C05武器师匠哈骏/C00加工武器。'),
  ('ov_hint.bin', 171, 5701633, '看见旁边那个/C04红色旋转的光环/C00了吗？那是通往/C05吟松谷/C00的传送点，走过去，踩在光环上就可以去到吟松谷了！'),
  ('ov_hint.bin', 172, 5701634, '那里有许多1级的/C10小蜗牛怪/C00，/C04左键单击/C00就可以进行攻击，如果你能够连续打败/C045只/C00小蜗牛怪，就可通过考验。'),
  ('ov_hint.bin', 173, 5701635, '通过考验后，去村子中间找/C05指引仙子柳飘/C00，她会教你学习第一个技能。'),
  ('ov_hint.bin', 174, 5701636, '恭喜你连续击败5只小蜗牛怪，顺利通过了第一个考验，现在可以去村子中间找/C05指引仙子柳飘/C00，她会教你学习新手技能。'),
  ('ov_hint.bin', 175, 5767169, '将/C05小生大仙/C00捡到的/C04两条围巾/C00给村里的/C05纪宓/C00送去。'),
  ('ov_hint.bin', 176, 5832705, '骑上小火鸟，将/C04白雪珍珠羹/C00送给/C05桃源村伊源/C00。/C05飞空艇仙子云璎/C00会免费将你传送过去。/C04限时30分钟/C00。'),
  ('ov_hint.bin', 177, 5832706, '帮助桃源村伊源完成丝帕上的题诗，将伊源的/C04丝帕/C00交给长乐村的/C05药衡/C00。'),
  ('ov_hint.bin', 178, 5898241, '去长乐村以北的/C05阳泉平原/C00，在/C10小野猪/C00身上收集/C042只野猪牙/C00，帮长乐村/C05武器师匠龙泉/C00加工武器。'),
  ('ov_hint.bin', 179, 5963777, '找到拥有/C04琥珀吊坠/C00的人，然后一同前往/C05桃源村/C00找/C05病叟/C00，他会告诉你搭救飞鸟和游鱼爱情的办法。'),
  ('ov_hint.bin', 18, 393217, '/C05龙城富商藤老爷/C00悬赏/C0430个银币/C00寻找/C04虎神之皮/C00。听说/C04龙城东郊/C00的/C05猎人伯山甫/C00知道虎神的下落。'),
  ('ov_hint.bin', 180, 5963778, '找到拥有/C04飞鸟画卷/C00的人，然后一同前往/C05桃源村/C00找/C05病叟/C00，他会告诉你搭救飞鸟和游鱼爱情的办法。'),
  ('ov_hint.bin', 181, 5963779, '进入赤枭出没地后，你和你的同伴要在/C041小时/C00以内找到两个转动的光环，然后各自踩到一个光环上，赤枭就会出现了！'),
  ('ov_hint.bin', 182, 5963780, '召唤出赤枭！打败它夺回飞鸟的魂魄！'),
  ('ov_hint.bin', 183, 6029313, '前往赤枭的巢穴，在/C041个小时/C00内找到/C10赤枭/C00，然后消灭它，解救飞鱼的魂魄！'),
  ('ov_hint.bin', 184, 6029314, '消灭赤枭！解救了飞鸟的魂魄！回长乐村告诉/C05寂仙子/C00这个好消息吧！'),
  ('ov_hint.bin', 185, 6094849, '接受阿歧老爹的任务，前往/C05青牛山脚/C00教训/C1020个牛头面具/C00，再去/C05修罗殿第一层/C00消灭/C1020个跳跳尸/C00。'),
  ('ov_hint.bin', 186, 6160385, '纯阳塔逃出了不少妖怪，在/C05大秦山原/C00附近有很多/C10飞天猴子和大熊/C00，分别打败/C1030只/C00。'),
  ('ov_hint.bin', 187, 6225921, '打败/C05大秦山原/C00上的/C10飞天猴子40只/C00和/C10大熊10只/C00，收集足够的灵气修补纯阳塔。'),
  ('ov_hint.bin', 188, 6291457, '巡卫大人需要/C05修罗殿/C00里的/C04孟婆汤25碗/C00，并且顺路清除/C1020个跳跳尸/C00，完成后交给巡卫阿芥。'),
  ('ov_hint.bin', 189, 6356993, '请到/C05修罗殿/C00歼灭/C1050个利爪鬼魂/C00。利爪鬼魂很厉害，请你路上多加小心！'),
  ('ov_hint.bin', 19, 393218, '在/C05华山/C00上打败10只小虎召唤出/C10虎神/C00，打败虎神得到/C04虎神之皮/C00，换取赏金，任务完成。'),
  ('ov_hint.bin', 190, 6422529, '/C05修罗殿/C00深处的/C10双头鬼侍/C00请你打败30只。让他们安静一段时间。'),
  ('ov_hint.bin', 191, 6488065, '今年狩猎的第一个任务是：/C10蓝鱼怪/C00和/C10玄武兽/C00各30个，请速去速回。玄武兽皮坚肉厚善于防御，不好对付。'),
  ('ov_hint.bin', 192, 6553601, '这次狩猎的目标是/C05出云城外大秦山/C00附近的/C10小猪神/C0020只、/C10雪女/C0020个和/C10玄武兽/C0020个。'),
  ('ov_hint.bin', 193, 6619137, '狩猎的目的是清除/C05幻萤谷/C00附近的/C10红鱼怪/C0030只、/C10金鱼怪/C0030个。这样城里的情侣又能到那边约会了。'),
  ('ov_hint.bin', 194, 6684673, '偷吃供品的妖物出没在/C05青牛山、青牛山脚/C00附近，教训/C10飞天猪/C0030只和/C10小猪神/C0020个，让它们从此不敢偷吃。'),
  ('ov_hint.bin', 195, 6750209, '今年的供品是/C05青牛山、大秦山、幻萤谷/C00附近的/C10苍狼皇、碧磷毒蛇、金鱼怪、小猪神和飞天猪/C00，每一种需要36只。'),
  ('ov_hint.bin', 196, 6815745, '就请阁下在这/C05函谷岭/C00附近驱杀/C10牛头面具/C0036只，我再为你一一道来。'),
  ('ov_hint.bin', 197, 6881281, '先下/C05修罗殿1层/C00附近驱杀/C10跳跳尸/C00七七四十九只，让我看看你的功夫。'),
  ('ov_hint.bin', 198, 6946817, '有两种魔匙：/C04利爪铁匙/C00和/C04利爪铜匙/C00。在/C05修罗殿/C00附近怪物身上掉落，请为巡卫阿芥各找10个回来。'),
  ('ov_hint.bin', 199, 7012353, '下/C05修罗殿第4层/C00附近驱杀/C10双头鬼侍/C0030只，这可是份苦差事。'),
  ('ov_hint.bin', 2, 131073, '在/C05龙城守城卫兵阿蒙/C00处接到委托：去/C05龙城西郊/C00消灭/C10木头人/C00，并收集/C0410个木头零件/C00。'),
  ('ov_hint.bin', 20, 458753, '帮龙城/C05矿工沙良/C00寻找丢失在/C05黄鹤遗址/C00里的/C04矿源之图/C00。矿源之图是在遇见/C10木箱怪/C00时丢失的。'),
  ('ov_hint.bin', 200, 7077889, '去/C05修罗殿/C00附近驱杀/C10双头鬼侍/C00，收集/C0410颗夜灵珠/C00，并且在/C10利爪鬼魂/C00身上收集/C0430颗暗灵珠/C00。'),
  ('ov_hint.bin', 201, 7143425, '/C05前天郊/C00有很多/C10QQ糖/C00。身上会掉很多糖果，请给我收集/C04甜蜜蜜/C0030个吧。'),
  ('ov_hint.bin', 202, 7208961, '这次的目标是/C05天都/C00附近的/C10仙苻/C0040只。'),
  ('ov_hint.bin', 203, 7274497, '请驱赶/C05后天郊/C00的/C10蜈蚣风筝/C00和/C10仙符/C00各36只。亏待不了你的。'),
  ('ov_hint.bin', 204, 7340033, '你去引开一下/C10火鸟/C0030只，分散它们的注意力。'),
  ('ov_hint.bin', 205, 7405569, '请你打败，蓬莱周围聚集的精灵，/C10风精灵/C00、/C10火精灵/C00、/C10雪精灵/C00、/C10冰精灵/C00，每一种都是20只。'),
  ('ov_hint.bin', 206, 7471105, '/C05前天郊/C00有很多/C10QQ糖/C00，请帮忙驱赶30只。'),
  ('ov_hint.bin', 207, 7536641, '蓬莱的/C10火鸟和蜈蚣风筝/C00身上有一种/C04火种/C00，是蓬莱仙灯的主要能量，最近火种很缺少，请你帮忙去寻找/C0430只火种/C00。'),
  ('ov_hint.bin', 208, 7602177, '女娲补天的时候，然烧的天火余烬落在蓬莱，就是现在的火精灵。扑灭60个/C10火精灵/C00，蓬莱的植物将会更加茂盛。'),
  ('ov_hint.bin', 209, 7667713, '/C05瑶池台/C00附近挑战/C10天判官/C0036只，只有强者才能在蓬莱立足。'),
  ('ov_hint.bin', 21, 458754, '在/C10木箱怪/C00身上找到了/C04矿源之图的碎片/C00，需要把地图碎片拿给/C05鬼谷先生/C00修补。'),
  ('ov_hint.bin', 210, 7733249, '仙女青鸾经过/C05千年之镜/C00时，被/C10水母球/C00弄伤了，请你到/C05千年之镜/C00附近驱杀/C10水母球/C0050只。'),
  ('ov_hint.bin', 211, 8192001, '分别从出云城的飞空艇仙子、出云名剑坊分店、出云天道山分店、道具师匠那里拿到一块神秘之石，交给出云城东北的天照大师。/C05/C00/C04/C00/C05/C00'),
  ('ov_hint.bin', 212, 8192002, '终于拿到四块神秘之石，赶紧将它们交给出云城东北的天照大师。/C04/C00/C05/C00'),
  ('ov_hint.bin', 213, 8257537, '分别从天都的飞空艇仙子、天都名剑坊分店、天都天道山分店、道具仙商那里拿到一块天命石残片，交给天都东北的天宫帝姬。/C05/C00/C04/C00/C05/C00'),
  ('ov_hint.bin', 214, 8257538, '终于拿到四块天命石残片，赶紧将它们交给天都东北的天宫帝姬。/C04/C00/C05/C00'),
  ('ov_hint.bin', 215, 8323073, '分别从楼兰城的飞空艇仙子、楼兰名剑坊分店、楼兰天道山分店、道具商人那里拿到一个命运沙漏，然后寻找到适合的人将它们交给对方。/C05/C00/C04/C00'),
  ('ov_hint.bin', 216, 8323074, '终于拿到个命运沙漏，将它们带到楼兰西北的摩迦那里，询问命运沙漏的保护者是谁。/C04/C00/C05/C00'),
  ('ov_hint.bin', 217, 8388609, '到瀛洲岛寻找黄鱼怪、玄武兽、苍狼，并杀死它们直到得到黄鱼胆、玄武甲和苍狼牙。/C05/C00/C10/C00/C04/C00'),
  ('ov_hint.bin', 218, 8388610, '带上黄鱼胆、玄武甲和苍狼牙，将它们交给天照大师。/C10/C00/C05/C00'),
  ('ov_hint.bin', 219, 8454145, '前往落霞坡和幻萤谷，在碧磷毒蛇、赤焰毒蛇和金鱼怪身上寻找碧鳞、赤鳞和金鳞。/C05/C00/C10/C00/C04/C00'),
  ('ov_hint.bin', 22, 458755, '由于地图碎片不全，无法修补，需要找齐所有的地图碎片。'),
  ('ov_hint.bin', 220, 8454146, '带上碧鳞、赤鳞和金鳞，将它们交给出云城的天照大师。/C04/C00/C05/C00'),
  ('ov_hint.bin', 221, 8519681, '在青牛山脚寻找被异化的牛头面具、小猪神和飞天猪，在它们身上找到异面符、异鼻符和异翅符。/C05/C00/C10/C00/C04/C00'),
  ('ov_hint.bin', 222, 8519682, '带上异面符、异鼻符和异翅符，将它们交给出云城的天照大师。/C10/C00/C05/C00'),
  ('ov_hint.bin', 223, 8585217, '接受天照大师的使命，前往蓬莱岛天都觐见玉皇大帝，寻求神的帮助。/C05/C00/C05/C00'),
  ('ov_hint.bin', 224, 8585218, '得到玉皇大帝的答复，返回出云城天照大师处复命。/C05/C00/C05/C00'),
  ('ov_hint.bin', 225, 8650753, '接受新的使命，前往/C05蓬莱岛天都/C00，向/C05玉皇大帝/C00求证守护云石之法。'),
  ('ov_hint.bin', 226, 8650754, '得到玉皇大帝的指点，前往修罗殿和幻萤洞寻找雪女的青丝和鬼侍之头。/C05/C00/C05/C00/C10/C00/C10/C00'),
  ('ov_hint.bin', 227, 8650755, '寻找到找雪女的青丝和鬼侍之头，交给天照大师，并告知其守护云石的密法。/C10/C00/C10/C00/C05/C00'),
  ('ov_hint.bin', 228, 8716289, '接受天宫帝姬的委托，在前天郊、后天郊和上天郊的仙符、火鸟和风妖精身上寻找符印、火印和风印。/C05/C00/C05/C00/C10/C00/C04/C00'),
  ('ov_hint.bin', 229, 8716290, '得到符印。'),
  ('ov_hint.bin', 23, 458756, '将地图碎片交给鬼谷先生，得到修补好的矿源之图。'),
  ('ov_hint.bin', 230, 8716291, '得到火印。'),
  ('ov_hint.bin', 231, 8716292, '得到风印。'),
  ('ov_hint.bin', 232, 8781825, '接受天宫帝姬的委托，在瑶池台和瑶台西的超级飞天猪、天翼魔和虾米小兵身上寻找猪耳、魔牙和虾臂。/C05/C00/C05/C00/C10/C00/C04/C00'),
  ('ov_hint.bin', 233, 8781826, '得到超级飞天猪的猪耳。'),
  ('ov_hint.bin', 234, 8781827, '得到天翼魔的魔牙。'),
  ('ov_hint.bin', 235, 8781828, '得到虾米小兵的虾臂。'),
  ('ov_hint.bin', 236, 8847361, '接受/C05天宫帝姬/C00的委托，在/C05千年之镜/C00的/C10水母球、豚仔和水兽/C00身上收集/C04水母唾液、豚仔汗液和水兽之泪/C00。'),
  ('ov_hint.bin', 237, 8847362, '得到水母唾液。'),
  ('ov_hint.bin', 238, 8847363, '得到豚仔汗液。'),
  ('ov_hint.bin', 239, 8847364, '得到水兽之泪。'),
  ('ov_hint.bin', 24, 458757, '将修补好的矿源之图交给矿工沙良，任务完成。'),
  ('ov_hint.bin', 240, 8912897, '接受/C05天宫帝姬/C00的委托，在/C05东海/C00的/C10大闸蟹、墨鱼仔和虾护卫/C00身上收集/C04铁蟹钳、铁爪鞭和铁龙须/C00。'),
  ('ov_hint.bin', 241, 8912898, '得到大闸蟹的铁蟹钳。'),
  ('ov_hint.bin', 242, 8912899, '得到墨鱼仔的铁爪鞭。'),
  ('ov_hint.bin', 243, 8912900, '得到虾护卫的铁龙须。'),
  ('ov_hint.bin', 244, 8978433, '接受/C05天宫帝姬/C00的委托，在/C05东海/C00的/C10人鱼巡逻、人鱼护卫和三头龙/C00身上寻找/C04人鱼珠、人鱼鳞和龙珠/C00。'),
  ('ov_hint.bin', 245, 8978434, '得到人鱼巡逻的人鱼珠。')
INSERT INTO "ov_named" ("tbl", "row_no", "ref_id", "name") VALUES
  ('ov_hint.bin', 246, 8978435, '得到人鱼护卫的人鱼鳞。'),
  ('ov_hint.bin', 247, 8978436, '得到三头龙的龙珠。'),
  ('ov_hint.bin', 248, 9043969, '接受/C05神庙长老摩迦/C00的委托，在/C05楼兰城郊/C00的/C10仙人掌小妖和巨食人花/C00身上搜集/C04仙人刺和食人花瓣/C00。'),
  ('ov_hint.bin', 249, 9043970, '得到仙人掌小妖的仙人刺。'),
  ('ov_hint.bin', 25, 524289, '龙城/C05客栈老板卢广/C00拜托你找/C05巧匠左慈/C00修补破裂的/C04珐琅花瓶/C00。'),
  ('ov_hint.bin', 250, 9043971, '得到巨食人花的食人花瓣。'),
  ('ov_hint.bin', 251, 9109505, '接受/C05神庙长老摩迦/C00的委托，在/C05沙台/C00的/C10沙虫和/C05落日沙丘/C00的/C10行尸/C00身上寻找/C04沙虫卵和防腐布/C00。'),
  ('ov_hint.bin', 252, 9109506, '得到沙虫卵。'),
  ('ov_hint.bin', 253, 9109507, '得到防腐布。'),
  ('ov_hint.bin', 254, 9175041, '接受神庙长老摩迦的委托，在蚂蚁沙地的兵蚁和守卫蚁身上寻找蚁须和蚁卵。/C05/C00/C05/C00/C10/C00/C04/C00'),
  ('ov_hint.bin', 255, 9175042, '得到兵蚁的蚁须。'),
  ('ov_hint.bin', 256, 9175043, '得到守卫蚁的蚁卵。'),
  ('ov_hint.bin', 257, 9240577, '接受/C05龙城盗墓王疾风/C00的委托，与朋友组队前往/C05黄鹤遗址/C00挑战/C10英雄刑天/C00。'),
  ('ov_hint.bin', 258, 9240578, '成功战胜/C10英雄刑天/C00，返回龙城向/C05盗墓王疾风/C00复命。'),
  ('ov_hint.bin', 259, 9306113, '接受/C05龙城捕头尉兴/C00的重任，与朋友组队前往/C05华山地宫/C00的最里层挑战想灭世的/C10不动明王/C00。'),
  ('ov_hint.bin', 26, 524290, '修补花瓶需要珐琅，/C05道具商人铃铛/C00处有上等的珐琅。'),
  ('ov_hint.bin', 260, 9306114, '击败/C10不动明王/C00，返回龙城向/C05捕头尉兴/C00复命。'),
  ('ov_hint.bin', 261, 9371649, '接受/C05出云城巡卫阿太/C00的重托，与朋友组队前往/C05函谷岭/C00消灭危害一方的/C10守护面具王/C00。'),
  ('ov_hint.bin', 262, 9371650, '消灭/C10守护面具王/C00，返回出云城向/C05巡卫阿太/C00复命。'),
  ('ov_hint.bin', 263, 9437185, '从/C05出云城浪人无名/C00口中得知修罗殿中的古怪，与朋友组队前往/C05修罗殿/C00中挑战/C10黑白无常/C00。'),
  ('ov_hint.bin', 264, 9437186, '击败/C10黑白无常/C00，返回出云城向/C05浪人无名/C00复命。'),
  ('ov_hint.bin', 265, 9502721, '在/C05天都天官尹喜/C00处接受任务，与朋友组队前往/C05瑶池台斩杀/C04五十个/C00/C10天判官/C00。'),
  ('ov_hint.bin', 266, 9502722, '成功斩杀/C04五十个/C00/C10天判官/C00，返回天都向/C05天官尹喜/C00复命。'),
  ('ov_hint.bin', 267, 9568257, '接受/C05天都二郎神杨戟/C00的重托，与朋友组队消灭在/C05瑶池台附近/C00出没的/C10超级魔王飞天猪/C00。'),
  ('ov_hint.bin', 268, 9568258, '消灭/C10超级魔王飞天猪/C00，返回天都向/C05二郎神杨戟/C00复命。'),
  ('ov_hint.bin', 269, 9633793, '接受/C05天都河上公/C00的托付，与朋友组队下/C05东海/C00，击败迷惑众生的/C10美人鱼王/C00。'),
  ('ov_hint.bin', 27, 524291, '道具商人铃铛要你拿/C049根虫蛹的蛹丝/C00交换珐琅，虫蛹通常出没在/C04华山地宫/C00。'),
  ('ov_hint.bin', 270, 9633794, '击败/C10美人鱼王/C00，返回天都向/C05河上公/C00复命。'),
  ('ov_hint.bin', 271, 9699329, '从/C05楼兰城掘金者阿克木/C00的口中得知/C10麒麟兽/C00再现人间，与朋友组队前往/C05流沙洞/C00一探究竟。'),
  ('ov_hint.bin', 272, 9699330, '击败/C10麒麟兽/C00，返回楼兰城告诉/C05掘金者阿克木/C00。'),
  ('ov_hint.bin', 273, 9764865, '在/C05楼兰城先知风涯/C00处接受新的使命，与朋友组队潜入/C05地下王宫/C00，消灭/C10死亡之后/C00。'),
  ('ov_hint.bin', 274, 9764866, '消灭/C10死亡之后/C00，返回楼兰城向/C05先知风涯/C00复命。'),
  ('ov_hint.bin', 275, 9830401, '在/C05楼兰城先知风涯/C00处接受另一半使命，与朋友组队再次潜入/C05地下王宫/C00，消灭/C10死亡之王/C00。'),
  ('ov_hint.bin', 276, 9830402, '消灭/C10死亡之王/C00，返回楼兰城向/C05先知风涯/C00复命。'),
  ('ov_hint.bin', 277, 9895937, '大年初一，/C05拜年娃娃/C00请你去向龙城的/C05巧匠左慈/C00姐姐询问制作/C04爆竹/C00的配方。'),
  ('ov_hint.bin', 278, 9895938, '制造爆竹需要/C04导火线、火药和红纸/C00，巧匠左慈建议你去找/C05矿工沙良/C00，他或许有/C04火药/C00。'),
  ('ov_hint.bin', 279, 9895939, '得到制作爆竹的火药，还缺少/C04导火线和和红纸/C00，矿工沙良告诉你/C05跑货商人南耘/C00那里也许有。'),
  ('ov_hint.bin', 28, 524292, '将蛹丝交给道具商人铃铛，换得珐琅。'),
  ('ov_hint.bin', 280, 9895940, '/C05跑货商人南耘/C00将红纸送给了你，并建议用/C04棉线/C00代替导火线，/C05妞妞妈/C00专门做针线活的，应该有棉线。'),
  ('ov_hint.bin', 281, 9895941, '从/C05妞妞妈/C00处得到棉线，回去交给/C05拜年娃娃/C00吧。'),
  ('ov_hint.bin', 282, 9961473, '大年初二，帮拜年娃娃收集至少/C0499张春联碎片/C00，龙城野外/C10绒绒兔、甲虫、蛾蛹怪和绿蛙兵/C00身上可能有。'),
  ('ov_hint.bin', 283, 10027009, '大年初三，拜年娃娃请你在/C05芳草林东、芳草林西、吟松谷东、吟松谷西/C00的/C10小黑狗/C00身上找出失踪的/C10哮天宝宝/C00。'),
  ('ov_hint.bin', 284, 10027010, '使用香喷喷的肉骨头，引出了调皮的/C10哮天宝宝/C00，回龙城交给拜年娃娃吧！'),
  ('ov_hint.bin', 285, 10092545, '大年初四吃饺子，去/C05桃源村/C00找/C05容大嫂/C00，为拜年娃娃带回香喷喷的新年/C04饺子/C00。'),
  ('ov_hint.bin', 286, 10092546, '容大嫂的饺子还缺少饺子馅，去/C05龙城东郊/C00找/C05猎人伯山甫/C00，取回新鲜的/C04猪肉/C00。'),
  ('ov_hint.bin', 287, 10092547, '在/C05猎人伯山甫/C00处得到新鲜的/C04猪肉/C00，会桃源村交给/C05容大嫂/C00。'),
  ('ov_hint.bin', 288, 10092548, '香喷喷的饺子做好啦，快去给龙城的拜年娃娃送去吧！'),
  ('ov_hint.bin', 289, 10158081, '在/C10步行鸟、蚯蚓、树妖、桃树妖、灯怪、夭夭、地藏小妖/C00身上找回散落的/C0410个财神红包/C00，到拜年娃娃处兑换压岁钱。'),
  ('ov_hint.bin', 29, 524293, '将珐琅交给巧匠左慈，得到修补好的珐琅花瓶。'),
  ('ov_hint.bin', 290, 10223617, '大年初六，帮拜年娃娃给/C05桃源村的壶公、哈大娘，长乐村的茶姥/C00送/C04请柬/C00，邀请他们参加龙城蟠桃宴。'),
  ('ov_hint.bin', 291, 10223618, '将请柬送给桃源村的壶公。'),
  ('ov_hint.bin', 292, 10223619, '将请柬送给桃源村的哈大娘。'),
  ('ov_hint.bin', 293, 10223620, '将请柬送给长乐村的茶姥。'),
  ('ov_hint.bin', 294, 10289153, '大年初七捉迷藏，在龙城四郊寻找拜年娃娃的/C05八个替身娃娃/C00，每个替身娃娃都会对应一句新年的魔力祝福。'),
  ('ov_hint.bin', 295, 10289154, '/C05替身娃娃新年快乐/C00祝您新的一年吉祥顺心！'),
  ('ov_hint.bin', 296, 10289155, '/C05替身娃娃万事如意/C00祝您新的一年万事如意！'),
  ('ov_hint.bin', 297, 10289156, '/C05替身娃娃身体健康/C00祝您新的一年身体健康！'),
  ('ov_hint.bin', 298, 10289157, '/C05替身娃娃学习顺利/C00祝您新的一年学习顺利！'),
  ('ov_hint.bin', 299, 10289158, '/C05替身娃娃恭喜发财/C00祝您新的一年恭喜发财！'),
  ('ov_hint.bin', 3, 131074, '收集/C0410个木头零件/C00，交给守城卫兵阿蒙，任务完成。'),
  ('ov_hint.bin', 30, 524294, '将修补好的珐琅花瓶交给客栈老板卢广，任务完成。'),
  ('ov_hint.bin', 300, 10289159, '/C05替身娃娃好运连连/C00祝您新的一年好运连连！'),
  ('ov_hint.bin', 301, 10289160, '/C05替身娃娃爱情甜蜜/C00祝您新的一年爱情甜蜜！'),
  ('ov_hint.bin', 302, 10289161, '/C05替身娃娃事业有成/C00祝您新的一年事业有成！'),
  ('ov_hint.bin', 303, 10354689, '在龙城的/C05城主成隍、鬼谷先生、小姑娘莺莺、观音院主持无恙和小米/C00处收集/C04五份春之雨露/C00，交给/C05绿色女神/C00。'),
  ('ov_hint.bin', 304, 10354690, '在城主成隍处获得一份“春之雨露”。'),
  ('ov_hint.bin', 305, 10354691, '在鬼谷先生处获得一份“春之雨露”。'),
  ('ov_hint.bin', 306, 10354692, '在小姑娘莺莺处获得一份“春之雨露”。'),
  ('ov_hint.bin', 307, 10354693, '在观音院主持无恙处获得一份“春之雨露”。'),
  ('ov_hint.bin', 308, 10354694, '在小米处获得一份“春之雨露”。'),
  ('ov_hint.bin', 309, 10420225, '替/C05春天女神/C00将/C04告示牌/C00交给郊外的/C05通玄先生、权寂道、猎人伯山埔和麻姑/C00。'),
  ('ov_hint.bin', 31, 720897, '龙城/C05守城卫兵阿炎/C00请你帮他准备一束/C04玫瑰花/C00送给老婆，买花要找卖花的/C05小姑娘莺莺/C00。'),
  ('ov_hint.bin', 310, 10420226, '将告示牌交给通玄先生。'),
  ('ov_hint.bin', 311, 10420227, '将告示牌交给权寂道。'),
  ('ov_hint.bin', 312, 10420228, '将告示牌交给猎人伯山埔。'),
  ('ov_hint.bin', 313, 10420229, '将告示牌交给麻姑。'),
  ('ov_hint.bin', 314, 10485761, '去/C05上古岳平原/C00找/C05通玄先生/C00，取一些新鲜的/C04春笋/C00交给春天女神。'),
  ('ov_hint.bin', 315, 10485762, '取到春笋，会龙城交给春天女神吧！'),
  ('ov_hint.bin', 316, 10551297, '使用/C05竹夹/C00，去野外捉/C1020只蚯蚓/C00，蚯蚓能够疏松土壤，产生植物生长的养料。'),
  ('ov_hint.bin', 317, 10616833, '春天女神请你去/C05桃源村哈大娘/C00家要一些美味的/C04春饼/C00来。'),
  ('ov_hint.bin', 318, 10616834, '帮哈大娘去龙城北郊/C05麻姑/C00那里取/C04一瓶纯净水/C00。'),
  ('ov_hint.bin', 319, 10616835, '得到纯净水，回桃源村交给哈大娘。'),
  ('ov_hint.bin', 32, 720898, '小姑娘莺莺的爹被恶狼咬伤，需要/C04醒梦铃/C00治疗。'),
  ('ov_hint.bin', 320, 10616836, '哈大娘做好了美味的春饼，快给春天女神送去吧。'),
  ('ov_hint.bin', 321, 10682369, '收集制作风筝的材料：长乐村拓老爹的/C04竹篾条/C00，龙城跑货商人南耘的/C04浆糊/C00，富商藤老爷的/C04白纸/C00。'),
  ('ov_hint.bin', 322, 10682370, '在长乐村拓老爹处得到/C04竹篾条/C00。'),
  ('ov_hint.bin', 323, 10682371, '在龙城跑货商人南耘处得到/C04浆糊/C00。'),
  ('ov_hint.bin', 324, 10682372, '在龙城富商藤老爷处得到/C04白纸/C00。'),
  ('ov_hint.bin', 325, 13172737, '请到/C05飞仙台/C00打败/C10笔仙/C0050个，然后请清除沿途的/C10云中兽/C0030个，云中兽很多，请你小心应付。'),
  ('ov_hint.bin', 326, 13238273, '狩猎的目标是/C05瑶台西/C00附近和/C05东海/C00的/C10虾米小兵/C0040只、/C10大闸蟹/C0030个。'),
  ('ov_hint.bin', 327, 13303809, '清除/C05遗忘之角/C00附近的/C10云中兽/C0050只、/C05千年之镜/C00附近的/C10水兽/C0020只，你若助我完成，必有谢意。'),
  ('ov_hint.bin', 328, 13369345, '/C05瑶台西/C00的/C10人鱼小兵/C00和/C05东海/C00/C10人鱼巡逻/C00，各清除50只，维护蓬莱净空。'),
  ('ov_hint.bin', 329, 13434881, '据说东海之底还有/C10三头龙/C00存在，只是从没有天兵见过，如真的存在，就请清灭40只，我会为你请功。'),
  ('ov_hint.bin', 33, 720899, '送一瓶醒梦铃给莺莺，得到一束玫瑰花。'),
  ('ov_hint.bin', 330, 13500417, '东海波澜怒吼，纵是我等天兵天将，也束手无策。若是能杀/C10大闸蟹30只、墨鱼仔040只、虾护卫30只/C00，更能证明身手。'),
  ('ov_hint.bin', 331, 13565953, '/C05千年之镜/C00附近，驱杀/C10水母球/C0036只，/C10豚仔/C0024只，/c10水兽/c0030只，为我蓬莱天兵扬威！'),
  ('ov_hint.bin', 332, 13631489, '负责巡逻的有2种，一种是/C10虾护卫/C00，一种是/C10人鱼巡逻/C00。你负责击杀它们各50只，吸引注意力。'),
  ('ov_hint.bin', 333, 13697025, '前往/C05东海/C00驱杀/C10人鱼小兵/C0050只，/C10人鱼巡逻/C0060只，/C10人鱼护卫/C0080只。天将徐甲将会给你丰厚奖赏。'),
  ('ov_hint.bin', 334, 13762561, '/C10三头龙/C00和/C10人鱼护卫/C00都是龙族后裔，三头龙有3头，善冰火毒。击杀/C10三头龙/C0040只和/C10人鱼护卫/C0050只。'),
  ('ov_hint.bin', 335, 13828097, '从/C05八仙的结界/C00中采集药材/C04党参/C007个。进入结界的方法，可以找到华山脚的/C05墨玉/C00姑娘询问。')
INSERT INTO "ov_named" ("tbl", "row_no", "ref_id", "name") VALUES
  ('ov_hint.bin', 336, 13893633, '进入/C05八仙的结界/C00，挑战15只/C10结界守护者/C00。进入结界的方法，可以找到华山脚的墨玉姑娘询问。'),
  ('ov_hint.bin', 337, 13959169, '到华山脚找到墨玉指点，进入/C05八仙的结界/C00，打败10只/C10结界巡逻者/C00。'),
  ('ov_hint.bin', 338, 14024705, '在封印冰凌魂魄/C05八仙的结界/C00内，获取矿石怪身上掉落的/C04方解石/C008个。'),
  ('ov_hint.bin', 339, 14090241, '到/C05纯阳塔/C00里面打狂暴的/C10魔熊/C006只，纯阳塔里怪物众多，组队进入会安全一些。'),
  ('ov_hint.bin', 34, 720900, '将玫瑰花交给守城卫兵阿炎，任务完成。'),
  ('ov_hint.bin', 340, 14155777, '到/C05纯阳塔/C00里面找寻美味的/C10沙姜/C006只，纯阳塔里有一种植物有机会掉落/C04沙姜/C00。'),
  ('ov_hint.bin', 341, 14221313, '到/C05纯阳塔/C00里杀/C10食心者/C008个，食心者非常厉害，请你多找些帮手！'),
  ('ov_hint.bin', 342, 14286849, '到/C05纯阳塔/C00里面找寻鲜红的/C04赤砂矿/C006个，纯阳塔里有一种矿物有机会掉落赤砂矿。'),
  ('ov_hint.bin', 343, 14352385, '天都/C05玉女/C00请你帮她收集/C0410颗电光水晶，10朵侍女的配花和一枚天泉宝珠/C00。'),
  ('ov_hint.bin', 344, 14352386, '这些宝物只在/C05天空之泉/C00的/C10电光水母、泉灵侍女和变异的泉灵/C00身上才有。'),
  ('ov_hint.bin', 345, 14417921, '天都/C05鲁班神匠/C00需要/C0430枚彼岸石/C00，请你帮他去/C05天空之泉/C00采集。'),
  ('ov_hint.bin', 346, 14483457, '天都/C05仙人元藏几/C00饱受情爱之苦，请你帮忙去/C05天空之泉/C00寻找/C04忘情草和无缘花/C00各20棵。'),
  ('ov_hint.bin', 347, 14548993, '替/C05太白金星/C00收集/C0430个冰冷的水晶和10张泉怪的皮毛，可分别在天空之泉的/C10冻结之魂和长毛泉怪/C00身上找到。'),
  ('ov_hint.bin', 348, 14614529, '在/C05落日沙丘西/C00的中部寻找楼兰城客栈老板/C05安夷琳/C00所说的/C05远古生物/C00，它长着人的面容和狮子的身体。'),
  ('ov_hint.bin', 349, 14680065, '进入神殿，寻找/C05斯芬尼克/C00的收藏。在神殿的第一层，/C05神使的幻身/C00会告诉你接下来该做些什么。'),
  ('ov_hint.bin', 35, 786433, '龙城舞姬月影/C00为了减肥只吃桃叶，她拜托你去采集/C042片桃叶。龙城北郊的桃树妖会掉落桃叶。/C050/C00/C05/C00/C04/C00'),
  ('ov_hint.bin', 350, 14745601, '帮助/C05神使的幻身/C00净化五颗/C10守护之石/C00：勇武、英知、荣誉，信义与兼爱。'),
  ('ov_hint.bin', 351, 14745602, '在神殿的第一层可以找到三颗守护之石，在神殿的第二层可以找到另外两颗。'),
  ('ov_hint.bin', 352, 14745603, '已经净化了/C10勇武之石/C00！'),
  ('ov_hint.bin', 353, 14745604, '已经净化了/C10英知之石/C00！'),
  ('ov_hint.bin', 354, 14745605, '已经净化了/C10荣誉之石/C00！'),
  ('ov_hint.bin', 355, 14745606, '已经净化了/C10信义之石/C00！'),
  ('ov_hint.bin', 356, 14745607, '已经净化了/C10兼爱之石/C00！'),
  ('ov_hint.bin', 357, 14811137, '消灭神殿中的/C10沙之王阿卡哈/C00！'),
  ('ov_hint.bin', 358, 15007745, '完成/C05落日的斯芬尼克/C00任务之后，落日沙丘的斯芬尼克会送你进/C05失落神殿/C00，找到/C10被缚的怨灵/C00并击败它。'),
  ('ov_hint.bin', 359, 15007746, '在失落的神殿底层击败被缚的怨灵，向楼兰城郊的荣光使者汇报你的胜利。'),
  ('ov_hint.bin', 36, 786434, '采集/C0420片桃叶/C00，交给舞姬月影，任务完成。'),
  ('ov_hint.bin', 360, 15073281, '进入天之峰，寻找古代神奇的/C05石碑/C00，通过这些石碑，/C05真徕/C00会给你进一步的指引。'),
  ('ov_hint.bin', 361, 15073282, '进入顶层/C05天之眼/C00后，对/C05盘古大神的石像/C00进行朝拜，他会给你最终的指引。'),
  ('ov_hint.bin', 362, 15073283, '成功开启护天门神身上的天之玄机，现在去朝拜盘古大神的石像吧！'),
  ('ov_hint.bin', 363, 15138817, '击败/C05试炼峰顶/C00中的/C10试炼之神兽/C00，获得进入下一层/C05飞升之天道/C00的资格。'),
  ('ov_hint.bin', 364, 15138818, '击败了试炼之神兽！现在可以进入下一层/C05飞升之天道/C00了！'),
  ('ov_hint.bin', 365, 15204353, '击败/C05飞升峰顶/C00中的/C10天道之神兽/C00，获得进入下一层/C05天之眼/C00的资格。'),
  ('ov_hint.bin', 366, 15204354, '击败了天道之神兽！现在可以进入下一层/C05天之眼/C00了！'),
  ('ov_hint.bin', 367, 15269889, '去/C05小桃源/C00找到/C05妖魔结界守卫（278,86）/C00，在他的帮助下组队进入结界，消灭里面所有的妖魔。'),
  ('ov_hint.bin', 368, 15269890, '去/C05阳泉平原右/C00找到/C05妖魔结界守卫（226,48）/C00，在他的帮助下组队进入结界，消灭里面所有的妖魔。'),
  ('ov_hint.bin', 369, 15269891, '去/C05碧野岭/C00找到/C05妖魔结界守卫（113,101）/C00，在他的帮助下组队进入结界，消灭里面所有的妖魔。'),
  ('ov_hint.bin', 37, 917505, '帮龙城/C05客栈老板卢广/C00带口信给/C05道具商人铃铛/C00。道具商人铃铛在城东南的/C04商会/C00附近。'),
  ('ov_hint.bin', 370, 15269892, '去/C05一叶岭/C00找到/C05妖魔结界守卫（306,102）/C00，在他的帮助下组队进入结界，消灭里面所有的妖魔。'),
  ('ov_hint.bin', 371, 15269893, '去/C05缘溪走廊/C00找到/C05妖魔结界守卫（83,103）/C00，在他的帮助下组队进入结界，消灭里面所有的妖魔。'),
  ('ov_hint.bin', 372, 15269894, '去/C05出云之角/C00找到/C05妖魔结界守卫（221,118）/C00，在他的帮助下组队进入结界，消灭里面所有的妖魔。'),
  ('ov_hint.bin', 373, 15269895, '去/C05大秦山原北/C00找到/C05妖魔结界守卫（252,100）/C00，在他的帮助下组队进入结界，消灭里面所有的妖魔。'),
  ('ov_hint.bin', 374, 15269896, '去/C05大秦山原南/C00找到/C05妖魔结界守卫（174,86）/C00，在他的帮助下组队进入结界，消灭里面所有的妖魔。'),
  ('ov_hint.bin', 375, 15269897, '去/C05落霞坡/C00找到/C05妖魔结界守卫（113,51）/C00，在他的帮助下组队进入结界，消灭里面所有的妖魔。'),
  ('ov_hint.bin', 376, 15269898, '去/C05青牛山南/C00找到/C05妖魔结界守卫（245,53）/C00，在他的帮助下组队进入结界，消灭里面所有的妖魔。'),
  ('ov_hint.bin', 377, 15269899, '去/C05阳泉平原左/C00找到/C05妖魔结界守卫（95,101）/C00，在他的帮助下组队进入结界，消灭里面所有的妖魔。'),
  ('ov_hint.bin', 378, 15269900, '已经消灭完所有的妖魔，回去试炼小仙处领取奖励吧。'),
  ('ov_hint.bin', 379, 15335425, '挑战魔神塔第一层的所有怪物。累积奖励进入第二层，奖励大幅提升，连清九层赢取至高名誉。'),
  ('ov_hint.bin', 38, 917506, '帮龙城/C05客栈老板卢广/C00带口信给/C05龙城名剑坊分店/C00。在/C05吕仙门人许栖岩/C00旁边。'),
  ('ov_hint.bin', 380, 15400961, '挑战魔神塔第二层的所有怪物。累积奖励进入第三层，奖励大幅提升，连清九层赢取至高名誉。'),
  ('ov_hint.bin', 381, 15466497, '挑战魔神塔第三层的妖魔；失败只能获得第三层鼓励奖，胜利后累积奖励进入第四层，奖励大幅提升，连清九层赢取至高名誉。'),
  ('ov_hint.bin', 382, 15532033, '挑战魔神塔第四层的妖魔；失败只能获得第四层鼓励奖，胜利后累积奖励进入第五层，奖励大幅提升，连清九层赢取至高名誉。'),
  ('ov_hint.bin', 383, 15597569, '挑战魔神塔第五层的妖魔；失败只能获得第五层鼓励奖，胜利后累积奖励进入第六层，奖励大幅提升，连清九层赢取至高名誉。'),
  ('ov_hint.bin', 384, 15663105, '挑战魔神塔第六层的妖魔；失败只能获得第六层鼓励奖，胜利后累积奖励进入第七层，奖励大幅提升，连清九层赢取至高名誉。'),
  ('ov_hint.bin', 385, 15728641, '挑战魔神塔第七层的妖魔；失败只能获得第七层鼓励奖，胜利后累积奖励进入第八层，奖励大幅提升，连清九层赢取至高名誉。'),
  ('ov_hint.bin', 386, 15794177, '挑战魔神塔第八层的妖魔；失败只能获得第八层鼓励奖，胜利后累积奖励进入第九层，奖励大幅提升，连清九层赢取至高名誉。'),
  ('ov_hint.bin', 387, 15859713, '挑战魔神塔第九层的妖魔；失败只能获得第九层鼓励奖，胜利后赢取至高名誉!'),
  ('ov_hint.bin', 388, 15925249, '端午节到了，开心果需要采集竹叶做粽子。'),
  ('ov_hint.bin', 389, 15990785, '在/C05飞升之天道/C00寻找/C10变异的腾蛇/C00，帮助/C05神秘仙人/C00找到/C04腾蛇的魂魄/C00。'),
  ('ov_hint.bin', 39, 917507, '帮龙城/C05客栈老板卢广/C00带口信给/C05龙城天道山分店/C00。在/C04果老门人寒山子/C00附近。'),
  ('ov_hint.bin', 390, 15990786, '你已经得到了/C04腾蛇的魂魄/C00，回去/C05神秘仙人/C00那交差吧，会有意想不到的收获。'),
  ('ov_hint.bin', 391, 16056321, '获得/C04灵光之石/C00的条件是/C045条小鱼/C00和/C04200个银币/C00，交给/C05飞升使者/C00即可。'),
  ('ov_hint.bin', 392, 16121857, '在幻幽平原四的西南角寻找一朵玫瑰——沉睡的花神（118/101），将它带回给兔子小白。/C05/C00'),
  ('ov_hint.bin', 393, 16187393, '收集2朵/C04紫菀花/C00和/C05影子迷泽/C00里20个/C04黑翼鬼蝠的翅膀/C00到合成炉合成出紫金香粉，唤醒沉睡的花神。'),
  ('ov_hint.bin', 394, 16252929, '花神的原神非常虚弱，需要回到祭坛休整。消灭幻幽平原四上个/C10抛石小鬼、矛卫者、冰魄玄妖/C00个各30个。'),
  ('ov_hint.bin', 395, 16252930, '已经成功收回幻瞳族人的祭坛，回去告诉花神这个好消息吧。'),
  ('ov_hint.bin', 396, 16318465, '乌老翁的女儿红苓被/C10妖化腾蛇/C00抓走了，前往/C04空灵平原一/C00消灭腾蛇救回红苓。一定要组队前往。'),
  ('ov_hint.bin', 397, 16318466, '已经成功解救红苓，他们父女能够团圆了。'),
  ('ov_hint.bin', 398, 16384001, '/C04心岛/C00里的/C10腐液幽魂/C00身上的/C05蓝瞳/C00结晶中，隐藏着乌老翁一族的湛蓝的眼睛，请找回来。'),
  ('ov_hint.bin', 399, 16384002, '已经找到了湛蓝的眼睛，乌老翁已经恢复幻瞳族人的身份。回去找他，他会解答你的问题。'),
  ('ov_hint.bin', 4, 196609, '在/C05龙城守城卫兵阿蒙/C00处接到委托：去/C05一叶岭或寻仙道/C00消灭/C10大蜗牛怪/C00，并收集/C0410个大蜗牛壳/C00。'),
  ('ov_hint.bin', 40, 917508, '帮龙城/C05客栈老板卢广/C00带口信给/C05富商藤老爷/C00。藤老爷在城东南的/C04娱乐场/C00里。'),
  ('ov_hint.bin', 400, 16449537, '快去找比赛/C05一号考官/C00答题，位置：/C05桃源东村（83/58）/C00，祝你一切顺利。/C10你必须在40分钟内完成比赛/C00'),
  ('ov_hint.bin', 401, 16449538, '完成本关后寻找/C05二号考官/C00答题，位置：/C05桃源东村（220/59）/C00'),
  ('ov_hint.bin', 402, 16449539, '完成本关后寻找/C05三号考官/C00答题，位置：/C05长乐东村（107/61）/C00'),
  ('ov_hint.bin', 403, 16449540, '完成本关后寻找/C05四号考官/C00答题，位置：/C05长乐东村（227/62）/C00'),
  ('ov_hint.bin', 404, 16449541, '完成本关后寻找/C05五号考官/C00答题，位置：/C05桃源西村（78/75）/C00'),
  ('ov_hint.bin', 405, 16449542, '完成本关后寻找/C05六号考官/C00答题，位置：/C05桃源西村（225/82）/C00'),
  ('ov_hint.bin', 406, 16449543, '完成本关后寻找/C05七号考官/C00答题，位置：/C05长乐西村（195/57）/C00'),
  ('ov_hint.bin', 407, 16449544, '完成本关后寻找/C05八号考官/C00答题，位置：/C05长乐西村（63/88）/C00'),
  ('ov_hint.bin', 408, 16515073, '快去找比赛/C05一号考官/C00答题，位置：/C05桃源东村（83/58）/C00，祝你一切顺利。/C10你必须在15分钟内完成比赛/C00'),
  ('ov_hint.bin', 409, 16515074, '完成本关后寻找/C05二号考官/C00答题，位置：/C05长乐东村（107/61）/C00'),
  ('ov_hint.bin', 41, 917509, '帮龙城/C05客栈老板卢广/C00带口信给/C05木匠左异/C00。木匠左异就住在客栈的后面。'),
  ('ov_hint.bin', 410, 16515075, '完成本关后寻找/C05三号考官/C00答题，位置：/C05桃源西村（78/75）/C00'),
  ('ov_hint.bin', 411, 16515076, '完成本关后寻找/C05四号考官/C00答题，位置：/C05长乐西村（195/57）/C00'),
  ('ov_hint.bin', 412, 16580609, '扁鸦想要/C0410个雪莲花/C00，你找无泪公进入冰河谷第二层的白河走廊帮他个忙吧。打冰精就会得到了。'),
  ('ov_hint.bin', 413, 16580610, '已经收集足够的雪莲花，赶紧去找扁鸦吧他可等不急了。'),
  ('ov_hint.bin', 414, 16646145, '冰河谷第二层白河走廊里面消灭/C10昏头的药师/C00，收集3颗飞升大补丸。另外收集/C0412个冰之火/C00'),
  ('ov_hint.bin', 415, 16646146, '顺利完成任务，回去无泪城找药师。'),
  ('ov_hint.bin', 416, 16711681, '帮助座山雕进入/C05消失的土地庙/C00消灭/C10蜂王/C00，你要先消灭地图里所有的隐藏陷阱，然后再消灭所有的蜜蜂蜂王才会出现。一定要组队完成。'),
  ('ov_hint.bin', 417, 16711682, '成功消灭蜂王，回去落日沙丘西告诉热合买提这个好消息。'),
  ('ov_hint.bin', 418, 16777217, '帮助热合买提进入/C05周庄梦蝶处里的尘源/C00消灭/C10沙王/C00，得到/C04缠缠之绵/C00。一定要组队完成。'),
  ('ov_hint.bin', 419, 16777218, '成功消灭沙王，得到缠缠之绵，去无泪城找座山雕跟他交换东西。'),
  ('ov_hint.bin', 42, 917510, '帮龙城/C05客栈老板卢广/C00带口信给/C05巧匠左慈/C00。巧匠左慈在城东南的/C04商会/C00里。'),
  ('ov_hint.bin', 420, 16777219, '已经从座山雕手上得到倒天牙，拿回去给热合买提吧。'),
  ('ov_hint.bin', 421, 16842753, '帮助热合买提进入/C05蝶恋谷的凝香冢/C00消灭/C10风后/C00，得到/C04定风珠/C00。一定要组队完成。'),
  ('ov_hint.bin', 422, 16842754, '成功消灭风后，得到定风珠，回去交给热合买提吧。'),
  ('ov_hint.bin', 423, 16908289, '帮助楚天乐进入/C05蝶恋谷/C00消灭/C10蝴蝶仙子和蝴蝶仙君/C00，得到/C04蝴蝶标本祝英台和蝴蝶标本梁山伯/C00。一定要组队完成。'),
  ('ov_hint.bin', 424, 16908290, '已经得到指定的道具，回去无泪城交给楚天乐。'),
  ('ov_hint.bin', 425, 16973825, '帮助谭风月进入/C05冰河谷/C00消灭/C1030个冰魂和20个冰魄/C00，')
INSERT INTO "ov_named" ("tbl", "row_no", "ref_id", "name") VALUES
  ('ov_hint.bin', 426, 16973826, '成功消灭指定数目的怪物，回去无泪城告诉谭风月。'),
  ('ov_hint.bin', 427, 17039361, '帮助花为媒进入/C05百里杜鹃/C00消灭/C1020个雷鸣走石和进入蝶恋谷消灭20个百花妖精/C00，百里杜鹃找无泪城座山雕进入、蝶恋谷找落日沙丘西的热合买提。'),
  ('ov_hint.bin', 428, 17039362, '成功消灭指定数目的怪物，回去无泪城告诉花为媒。'),
  ('ov_hint.bin', 429, 17104897, '帮助热合买提到无泪城给座山雕传个话，让他将缠缠之绵还给热合买提。'),
  ('ov_hint.bin', 43, 917511, '帮龙城/C05客栈老板卢广/C00带口信给/C05仓库管理员无忧/C00。无忧通常在城中心的双龙雕像旁。'),
  ('ov_hint.bin', 430, 17104898, '已经拿到缠缠之绵，回去落日沙丘西给热合买提吧。'),
  ('ov_hint.bin', 431, 17170433, '进入冰河谷，寻找雪窟地狱中的/C10“谭香雪”/C00，打碎它就能得到/C04泪之结晶/C00，一定要组队完成。'),
  ('ov_hint.bin', 432, 17170434, '成功打碎谭香雪获得泪之结晶，无泪公的委托已经完成。'),
  ('ov_hint.bin', 433, 19660801, '为帮助你更快成长，仙人赐予了你/C04三个锦囊/C00，在/C0510、20、30/C00级的时候，依次打开它们，你将获得神的馈赠。'),
  ('ov_hint.bin', 434, 19660802, '拆开第一个锦囊，获得加工3的12级职业武器一把，30银币。'),
  ('ov_hint.bin', 435, 19660803, '拆开第二个锦囊，获得打孔2的20级职业装一件，赤铜20块、蛋壳5个，伤害-10的镶嵌用石肤+5属性卡两张。'),
  ('ov_hint.bin', 436, 19660804, '拆开第三个锦囊，获得限量版超人气宠物闪电鼠和奇幻坐骑独角兽。'),
  ('ov_hint.bin', 437, 19726337, '帮助龙城的三位明星找回被怪物哄抢去的“唱片”，唱片有可能出现在任何一只怪物身上哦！'),
  ('ov_hint.bin', 438, 19791873, '长乐村村民需要你的帮助，帮助他们你会获得散落的/C04四张藏宝图碎片/C00。请在/C05五个小时/C00内收集齐所有碎片。'),
  ('ov_hint.bin', 439, 19791874, '藏宝图碎片一：1级的时候，帮助/C05小生大仙/C00消灭5只小蜗牛怪，并在/C05指引仙子飘柳/C00处学习新手技能。'),
  ('ov_hint.bin', 44, 917512, '帮龙城/C05客栈老板卢广/C00带口信给/C05无恙大师/C00。无恙大师就在城东北的/C04观音院/C00里。'),
  ('ov_hint.bin', 440, 19791875, '藏宝图碎片二：/C05小叶/C00是位漂亮乖巧的小姑娘，当你2级的时候，也许很乐意帮她收集20只蜗牛壳。'),
  ('ov_hint.bin', 441, 19791876, '藏宝图碎片三：5级时，先帮村里的纪宓做完竹篓任务，然后帮/C05跑货商人药衡/C00送信给桃源村的心上人，也是一桩美事哦。'),
  ('ov_hint.bin', 442, 19791877, '藏宝图碎片四：6级的时候，如果你能帮村里的/C05拓老爹/C00求来“茶姥的药膏”，他一定会非常感激你的。'),
  ('ov_hint.bin', 443, 19791878, '完成“小试身手”任务，得到藏宝图碎片一。'),
  ('ov_hint.bin', 444, 19791879, '完成“蜗牛壳”任务，得到藏宝图碎片二。'),
  ('ov_hint.bin', 445, 19791880, '完成“货郎的情意”任务，得到藏宝图碎片三。'),
  ('ov_hint.bin', 446, 19791881, '完成“茶姥的药膏”任务，得到藏宝图碎片四。'),
  ('ov_hint.bin', 447, 19791882, '已经收集齐四张藏宝图碎片，将它们交给/C05桃源村跑货商人成佑/C00吧！'),
  ('ov_hint.bin', 448, 19791883, '用藏宝图在桃源村跑货商人成佑处换得/C04Q币宝箱/C00，请在/C0512个小时/C00内打开它领取Q币，打开宝箱要求/C0510级/C00。'),
  ('ov_hint.bin', 449, 19857409, '很幸运，你获得了拥有强大力量的/C04三个粽子/C00，在/C0510、25、40/C00级的时候，依次吃掉它们，你将获得神的馈赠。'),
  ('ov_hint.bin', 45, 917513, '帮龙城/C05客栈老板卢广/C00带口信给/C05护城将军石沛/C00。护城将军石沛在/C04衙门/C00里。'),
  ('ov_hint.bin', 450, 19857410, '10级之后，吃掉第一个神奇的粽子，仙人聆听到你的心声，将馈赠你神秘的礼物。'),
  ('ov_hint.bin', 451, 19857411, '25级之后，吃掉第二个神奇的粽子，仙人聆听到你的心声，将馈赠你神秘的礼物。'),
  ('ov_hint.bin', 452, 19857412, '40级之后，吃掉第三个神奇的粽子，仙人聆听到你的心声，将馈赠你神秘的礼物。'),
  ('ov_hint.bin', 453, 19922945, '到龙城飞空艇仙子处，领取龙城的幻想通行证。'),
  ('ov_hint.bin', 454, 19922946, '到出云飞空艇仙子处，领取出云的幻想通行证。'),
  ('ov_hint.bin', 455, 19922947, '到天都飞空艇仙子处，领取天都的幻想通行证。'),
  ('ov_hint.bin', 456, 19922948, '到楼兰飞空艇仙子处，领取楼兰的幻想通行证。'),
  ('ov_hint.bin', 457, 19922949, '所有的幻想通行证已经收集完成，拿回去给intel天使吧。'),
  ('ov_hint.bin', 458, 19988481, '到野外打怪，帮助intel天使收集100个酷睿碎片，她就可以重组酷睿飞行器了。'),
  ('ov_hint.bin', 459, 19988482, '收集100个酷睿碎片已经完成，交给intel天使你会得到奖励。'),
  ('ov_hint.bin', 46, 917514, '帮龙城/C05客栈老板卢广/C00带口信给/C05包打听/C00。包打听家就住在城北。'),
  ('ov_hint.bin', 460, 20054017, '收集/C105个傀儡零件，5个废弃的武器，5个失落的灵魂，10个蓝鱼鳞/C00，召唤出迷失的龙魂。'),
  ('ov_hint.bin', 461, 20119553, '进入火源涧，消灭/C10古玉魔灵/C00，取回/C04仙云古玉/C00。一定要组队完成。'),
  ('ov_hint.bin', 462, 20119554, '已经得到仙云古玉，回去广成子处交给他吧。'),
  ('ov_hint.bin', 463, 20185089, '想要左慈帮忙锻造法宝，必须先收集/C055个妖魔内丹；5个不明液体；3个天魔之眼。'),
  ('ov_hint.bin', 464, 20250625, '想要得到神器法宝，必须要进入/C04天魔洞窟/C00，消灭/C10九天蛰眠之龙/C00。一定要组队完成。'),
  ('ov_hint.bin', 465, 20250626, '神兽已经被消灭了，元藏几应该会非常高兴了。'),
  ('ov_hint.bin', 466, 20316161, '找来/C0410个符咒；迷途的密药10个；暗灵珠15个/C00，雷神龙赫就会告诉你法宝的秘密。'),
  ('ov_hint.bin', 467, 20381697, '进入火源涧，消灭/C10火兜率邪火/C00取得/C04兜率邪火/C00。一定要组队完成。然后加上5个天泉蟹甲交给仙人元藏几吧。'),
  ('ov_hint.bin', 468, 20381698, '顺利取得兜率邪火，带上天泉蟹甲去找元藏几。'),
  ('ov_hint.bin', 469, 20447233, '神庙长老还真奇怪，要求你要将手中的兜率玄天令换成对应的另外一个，没办法。'),
  ('ov_hint.bin', 47, 917515, '帮龙城/C05客栈老板卢广/C00带口信给/C05寄售商人谷计/C00。寄售商人谷计在城东南的/C04商会/C00里。'),
  ('ov_hint.bin', 470, 20512769, '进入/C05天魔洞窟/C00，消灭/C10试炼神将/C00，就可以完成进阶的考验了。一定要组队完成。'),
  ('ov_hint.bin', 471, 20512770, '成功消灭试炼神将，回去让元藏几炼造出进阶后的神器法宝。'),
  ('ov_hint.bin', 472, 20578305, '客栈老板富财请求你去教许无泪城周围的流民野徒，需要击杀/C05无泪南郊/C00/C1030个盾卫者（敏）、/C05无泪东郊/C0030个涂山妖民、/C05无泪盆地/C0030个魔念者/C00。'),
  ('ov_hint.bin', 473, 20578306, '已经击杀完指定数目的怪物，回去答复客栈老板富财吧。'),
  ('ov_hint.bin', 474, 20643841, '拿着客栈老板富财给的凤尾去找天境阁长老，也许他知道如何将兜率玄都仙符提升到更高级别。'),
  ('ov_hint.bin', 475, 20643842, '需要收集/C1015个天桑果、15个地勒草和15个水延花/C00，这些东西分别在/C10幻幽平原一的丧气浊液（速）和赤血妖晶及无泪盆地的持斧小鬼/C00身上收集到，击杀他们的时候就有一定几率获得,然后交给天境阁'),
  ('ov_hint.bin', 476, 20643843, '已经收到到指定数目的材料，回去找天镜阁长老。'),
  ('ov_hint.bin', 477, 20709377, '在冰河谷教训/C1025个冰魄、25个冰魂和25个冰精/C00就行了，不过他们一般都隐藏在其他空间里面，能力都很强，建议你找朋友一起去比较好，完成之后去找道具商人卿泓。'),
  ('ov_hint.bin', 478, 20709378, '已经教训了指定数目的怪物，回去找道具商人卿泓吧。'),
  ('ov_hint.bin', 479, 20774913, '在（幻幽平原二）打败邪虎之后就能获得/C10凤头/C00。不过这只虎非常厉害，一定要组队完成。'),
  ('ov_hint.bin', 48, 917516, '帮龙城/C05客栈老板卢广/C00带口信给/C05鬼谷先生/C00。鬼谷先生在城西南的/C04书店/C00旁边。'),
  ('ov_hint.bin', 480, 20774914, '去将/C10凤尾、凤羽、凤爪和凤头/C00拿去合成/C10金凤液/C00再回去找天眼侍者玄天。'),
  ('ov_hint.bin', 481, 20840449, '教训/C10幻幽平原二的30只魔祭者、幻幽平原三的30只刚破鬼和镜湖北岸的30只剧毒鬼蝎/C00再回来报告给城门守卫札图。'),
  ('ov_hint.bin', 482, 20840450, '已经完成了任务，回去告诉守卫札图这个好消息。'),
  ('ov_hint.bin', 483, 20905985, '分别打败/C10幻幽平原四的30只冰魄玄妖、幻幽平原四的30只矛卫者和镜湖北岸的30只涂山魔（速）/C00，获得尘心。'),
  ('ov_hint.bin', 484, 20905986, '拿着/C10尘心/C00去找神女香提。'),
  ('ov_hint.bin', 485, 20971521, '进入百里杜鹃打败/C1030只沙虫骑士和30只沙傀儡/C00，里面的怪物非常厉害，建议你和朋友一起进去完成后回去找无泪城主绝聆。'),
  ('ov_hint.bin', 486, 20971522, '消灭了指定数目的怪物，完成了无泪城主的考验。'),
  ('ov_hint.bin', 487, 21037057, '打败灵虚兽获得/C10灵虚草/C00之后再去找莫须，这种怪物一般在境湖出没，一定要组队完成。'),
  ('ov_hint.bin', 488, 21037058, '成功消灭灵虚兽，得到了灵虚草，回去交给莫须就行。'),
  ('ov_hint.bin', 489, 21102594, '你已经收集齐指定数目的怪物灵魂，回去无泪城找楚乐天交任务吧。'),
  ('ov_hint.bin', 49, 917517, '帮龙城/C05客栈老板卢广/C00带口信给/C05歌姬骊姜/C00。歌姬骊姜在城东南的/C04娱乐场/C00里。'),
  ('ov_hint.bin', 490, 21168129, '在野外的/C10灵斑蜥（灵）、腐气浊液（速）/C00身上一定概率掉落/C05火行令牌/C00，带着火行令牌才能进入/C04绿野仙境三层/C00，打败/C10结界守护师（火）（326，296）/C00通过结界的考验。'),
  ('ov_hint.bin', 491, 21168130, '已经成功消灭结界守护师（火），通过了结界的考验，回到结界入口处那告诉门神吧！'),
  ('ov_hint.bin', 492, 21233665, '进入/C04绿野仙境四层/C00打败/C10云生兽（任务）（227，245）/C00，重新燃起它体内的光明之炎！'),
  ('ov_hint.bin', 493, 21233666, '光明之炎已经重燃，回去绿野仙境门神处交任务吧。'),
  ('ov_hint.bin', 494, 21299201, '进入/C04绿野仙境五层/C00打败/C10火德真君（任务）（181，86）/C00，寻找邪恶力量的来源。'),
  ('ov_hint.bin', 495, 21299202, '火德真君（任务）已经被打败，打开它的真君宝箱看看到底有什么东西。'),
  ('ov_hint.bin', 496, 21299203, '获得仙境魔盒，散发着邪恶之气，赶紧拿回去给门神确认究竟是什么东西。'),
  ('ov_hint.bin', 497, 21364737, '在野外的/C10石鳞地龙、怨灵之石（速）/C00身上一定概率掉落/C05金行令牌/C00，带着金行令牌才能进入/C04上古遗迹一层/C00，打败/C10结界守护师（金）（321，61）/C00通过结界的考验。'),
  ('ov_hint.bin', 498, 21364738, '已经成功消灭结界守护师（金），通过了结界的考验，回到结界入口处那告诉门神吧！'),
  ('ov_hint.bin', 499, 21430273, '进入/C04上古遗迹二层/C00打败/C10封印石守卫（任务）（463，75）/C00，只有打败他才有办法打破封印。'),
  ('ov_hint.bin', 5, 196610, '收集/C0410个大蜗牛壳/C00，交给守城卫兵阿蒙，任务完成。'),
  ('ov_hint.bin', 50, 917518, '帮龙城/C05客栈老板卢广/C00带口信给/C05宠物商人天衣/C00。宠物商人天衣在城西南的/C04宠物店/C00里。'),
  ('ov_hint.bin', 500, 21430274, '封印石守卫已经被消灭，出现封印石！只要打碎封印石就可以释放亡灵。'),
  ('ov_hint.bin', 501, 21430275, '封印石已经打碎，回去跟上古遗迹门神交待一下事情的经过吧。'),
  ('ov_hint.bin', 502, 21495809, '进入/C04上古遗迹三层/C00打败/C10蚩尤之魂（任务）（316，208）/C00，它仍然束缚着远古战场的亡灵，两方的冲突一触即发。'),
  ('ov_hint.bin', 503, 21495810, '蚩尤之魂已经被打败，亡灵得到释放。现在就回去寻找上古遗迹门神，让它处理剩下的事情吧。'),
  ('ov_hint.bin', 504, 21561345, '进入/C04绿野仙境/C00不管遇见什么人都去询问一下曹仙人的事情。'),
  ('ov_hint.bin', 505, 21561346, '根据龙使圣邪的要求，打开绿野仙境中存在的/C055个蓝色光环的封印点/C00，她才会将精气宝珠归还。赶紧去寻找吧，封印点分别在绿野仙境1、2、3、4、5层。'),
  ('ov_hint.bin', 506, 21561347, '封印点已经全部打开，回去龙使圣邪处交任务吧。'),
  ('ov_hint.bin', 507, 21626881, '龙魂璃吻被镜湖的怪物所夺，消灭个掷斧小鬼、个即可夺回龙魂/C05/C00/C103030石鳞地龙和30个怨灵之石/C00'),
  ('ov_hint.bin', 508, 21626882, '龙魂璃吻已经被顺利救出，回到了谭风月处。你也赶紧回去看看。'),
  ('ov_hint.bin', 509, 21692417, '到/C05心岛/C00消灭/C1050个蓝魔妖晶/C00，帮助花为媒收集蓝晶花种子。'),
  ('ov_hint.bin', 51, 917519, '帮龙城/C05客栈老板卢广/C00带口信给/C05飞空艇仙子云翘/C00。飞空艇仙子云翘在城东南的花坛边。'),
  ('ov_hint.bin', 510, 21692418, '蓝晶花已经出现，消灭它就能得到蓝晶花种子,然后带着种子回去找花为媒。'),
  ('ov_hint.bin', 511, 21757953, '消灭心岛的个腐尸鬼气（敏）和空灵平原一的个钢翅甲虫（甲），释放龙魂狻猊。/C05/C00/C1030/C05/C0030/C00'),
  ('ov_hint.bin', 512, 21757954, '已经得到龙魂狻猊，带回去给花为媒。'),
  ('ov_hint.bin', 513, 21823489, '神坛祭司风史已经知道拯救龙魂的方法，到/C05心岛/C00消灭/C1050个古石妖/C00，召唤出来石妖王（任务），消灭石妖王得到石妖王结晶。'),
  ('ov_hint.bin', 514, 21823490, '石妖王已经出现，消灭它得到石妖王结晶，然后拿回去给神坛祭司风史。'),
  ('ov_hint.bin', 515, 23068673, '进入家族采石场，收集/C04100个家族磐石/C00即可完成任务。')
INSERT INTO "ov_named" ("tbl", "row_no", "ref_id", "name") VALUES
  ('ov_hint.bin', 516, 23068674, '已经收集到足够的家族磐石，回去交任务吧。'),
  ('ov_hint.bin', 517, 23134209, '进入家族采石场，收集/C04150个灵魂石/C00即可完成任务。'),
  ('ov_hint.bin', 518, 23134210, '已经收集到足够的灵魂石，回去交任务吧。'),
  ('ov_hint.bin', 519, 23199745, '帮助笑仙人周立民收集9只/C04禁锢的极光/C00，只要消灭在/C05上古遗迹/C00中特定时间才会出现的/C10蚩尤之魂/C00，才能得到。请组队前往。'),
  ('ov_hint.bin', 52, 1048577, '龙城的/C05妞妞妈/C00请你帮忙找/C05妞妞/C00回家。'),
  ('ov_hint.bin', 520, 23199746, '极光已经集齐，回去天都找笑仙人周立民（88，121）吧。'),
  ('ov_hint.bin', 521, 23265281, '进入/C05异龙之巢/C00，杀死/C10异种龙后/C00获得/C04混沌鼎炉/C00，只有此物才能解开极光上的封印。需要先消灭全部龙兵，异种龙后才会出现。记住只有一次机会，一旦出了副本就无法在进去了，任务失败�'),
  ('ov_hint.bin', 522, 23265282, '成功消灭了异种龙后，得到了混沌鼎炉，赶紧回去无泪城让无泪公看看。'),
  ('ov_hint.bin', 523, 23330817, '进入/C05隐魂之森/C00，探索/C10玉清灵泉/C00，找到真正的玉清灵泉后，获得/C04玉清灵泉/C00，这是净化法宝的上品。真正的灵泉只有一个，你有三次机会尝试探索。切记一旦出了副本就无法在进去了，任务�'),
  ('ov_hint.bin', 524, 23330818, '已经找到真正的玉清灵泉，带回去让安期生帮忙净化法宝。'),
  ('ov_hint.bin', 525, 23396353, '带着/C04魂笛/C00进入到/C05上古遗迹/C00那定时出现的蚩尤之魂所在之处，在蚩尤之魂尚存之时使用魂笛，就能召唤出/C10万载石枷/C00。魂笛使用后就会消失，你只有一次的机会。'),
  ('ov_hint.bin', 526, 23396354, '使用了魂笛，召唤出了万载石枷。快点找到属于你的万载石枷消灭它，就能在当地释放薛冰仙子。/C05切记你只能在蚩尤之魂死亡前消灭万载石枷才有效/C00。'),
  ('ov_hint.bin', 527, 23396355, '成功消灭万载石枷，薛冰仙子已经获得释放，去找到属于你的npc跟她对话吧。副本一旦关闭她就会消失了，请抓紧机会。'),
  ('ov_hint.bin', 528, 23461889, '帮助铁柱仙田翔收集/C047个铜花瞬豹魂/C00，据说是附身在了/C05上古遗迹/C00之中定时出现的怪物/C10蚩尤之魂/C00的身上，请组队前往。'),
  ('ov_hint.bin', 529, 23461890, '铜花瞬豹魂已经集齐，回去楼兰找铁柱仙田翔（156，35）吧。'),
  ('ov_hint.bin', 53, 1048578, '找到妞妞，她的/C05小狗大头/C00不见了，到/C05龙城东郊/C00找小狗大头。'),
  ('ov_hint.bin', 530, 23527425, '进入/C05月牙塔/C00，打败/C10憎恨囚牢/C00后获得/C04凌天塔魄或者霄天塔魄/C00，然后根据身上的法宝材料配合成正确的组合炼造法宝。你只有一次机会，一旦出了副本就无法在进去了，任务失败后请取消任�'),
  ('ov_hint.bin', 531, 23527426, '成功打败憎恨囚牢，获得法宝材料，请将正确的材料组合交给楼兰仙人刘丹（50，87）。如果你得到的材料不是正确的组合，就找其他的勇士交换吧！'),
  ('ov_hint.bin', 532, 23592961, '带着/C04冥哨/C00进入到/C05上古遗迹/C00那定时出现的蚩尤之魂所在之处，在蚩尤之魂尚存之时使用冥哨，就能召唤出/C10狂魔之魄/C00。冥哨使用后就会消失，你只有一次的机会。'),
  ('ov_hint.bin', 533, 23592962, '使用了冥哨，召唤出了狂魔之魄。快点找到属于你的狂魔之魄消灭它，就能在当地释放古仙纪泽锋。/C05切记你必须在5分钟内消灭狂魔之魄/C00，否则它就会消失，任务失败。'),
  ('ov_hint.bin', 534, 23592963, '成功释放出古仙纪泽锋去找到属于你的npc跟他对话吧。副本一旦关闭她就会消失了，请抓紧机会。'),
  ('ov_hint.bin', 535, 23658497, '进入/C05月轮天经塔/C00，打败/C10世外异妖/C00后获得/C04魂咒石/C00，只有这样仙人陈烜才肯帮忙炼造法宝。你只有一次机会，一旦出了副本就无法在进去了，任务失败后请取消任务吧。你只能独自前往。'),
  ('ov_hint.bin', 536, 23658498, '已经得到魂咒石，回去出云给仙人陈烜（173，37）吧。'),
  ('ov_hint.bin', 537, 26214401, '去龙城南郊或北郊收集/C045个金蛋/C00，/C04火鸟蛋/C00的巢里会掉落金蛋。'),
  ('ov_hint.bin', 538, 26214402, '将收集的5个金蛋送给/C05小姑娘莺莺/C00。'),
  ('ov_hint.bin', 539, 26214403, '送出金蛋后，现在可以回去找蓟子训回复任务了。'),
  ('ov_hint.bin', 54, 1048579, '在龙城东郊找到小狗大头，回去告诉妞妞。'),
  ('ov_hint.bin', 540, 26279937, '去村外/C04白兔/C00身上寻找/C04三个凭证/C00，证明自己是有缘人。'),
  ('ov_hint.bin', 541, 26345473, '接受刺客考验：去野外/C04不掉线/C00连续打败/C0430只闪电鼠/C00。'),
  ('ov_hint.bin', 542, 26411009, '去野外五种怪物：/C04白兔、甲虫、食人花、蚯蚓、小野猪/C00身上寻找/C04五枚金丹/C00。'),
  ('ov_hint.bin', 543, 26411010, '在白兔身上找到一枚金丹。'),
  ('ov_hint.bin', 544, 26411011, '在甲虫身上找到一枚金丹。'),
  ('ov_hint.bin', 545, 26411012, '在食人花身上找到一枚金丹。'),
  ('ov_hint.bin', 546, 26411013, '在蚯蚓身上找到一枚金丹。'),
  ('ov_hint.bin', 547, 26411014, '在小野猪身上找到一枚金丹。'),
  ('ov_hint.bin', 548, 26411015, '将五枚金丹交给龙城裴谌，任务完成，就职为战士。'),
  ('ov_hint.bin', 549, 26476545, '帮龙城/C05许栖岩/C00收集养花的肥料：小野猪的/C04野猪牙15个/C00，火鸟蛋的/C04蛋壳10个/C00、桃树妖的/C04桃叶5片/C00。'),
  ('ov_hint.bin', 55, 1048580, '告诉妞妞已经找到小狗大头，她答应马上带着小狗回家。'),
  ('ov_hint.bin', 550, 26542081, '帮桃源村的/C05病叟/C00找村里的/C05妙仙子/C00求药。'),
  ('ov_hint.bin', 551, 26542082, '妙仙子指示玩家去找/C05桃树仙/C00要/C04三根桃枝/C00。'),
  ('ov_hint.bin', 552, 26542083, '得到三根桃枝。'),
  ('ov_hint.bin', 553, 26542084, '将三根桃枝交给妙仙子，得到一瓶/C04玉露/C00。'),
  ('ov_hint.bin', 554, 26542085, '将玉露交给病叟，任务完成。'),
  ('ov_hint.bin', 555, 26607617, '帮长乐村的/C05寂仙子/C00找村里的/C05善仙子/C00求药。'),
  ('ov_hint.bin', 556, 26607618, '善仙子指示玩家去找/C05柳树仙/C00要/C04三根柳枝/C00。'),
  ('ov_hint.bin', 557, 26607619, '得到三根柳枝。'),
  ('ov_hint.bin', 558, 26607620, '将三根柳枝交给善仙子，得到一瓶/C04玉露/C00。'),
  ('ov_hint.bin', 559, 26607621, '将玉露交给寂仙子，任务完成。'),
  ('ov_hint.bin', 56, 1048581, '回到妞妞家，告诉妞妞妈，任务完成。'),
  ('ov_hint.bin', 560, 26673153, '帮龙城的/C05蓟子训/C00送/C04五味紫金丸/C00给城里的/C05盗墓王疾风、守城卫兵阿基、包打听老公、护城将军石沛、宠物商人天衣/C00。'),
  ('ov_hint.bin', 561, 26673154, '将紫金丸送给盗墓王疾风。'),
  ('ov_hint.bin', 562, 26673155, '将紫金丸送给守城卫兵阿基。'),
  ('ov_hint.bin', 563, 26673156, '将紫金丸送给包打听老公。'),
  ('ov_hint.bin', 564, 26673157, '将紫金丸送给护城将军石沛。'),
  ('ov_hint.bin', 565, 26673158, '将紫金丸送给宠物商人天衣。'),
  ('ov_hint.bin', 566, 26673159, '送完药后，回复蓟子训，任务完成。'),
  ('ov_hint.bin', 567, 26738689, '去西南方向的上古岳平原寻找一位隐居的/C05通玄先生/C00，打听治疗怪病的药材。'),
  ('ov_hint.bin', 568, 26738690, '那个不承认自己是通玄先生的怪人，要你先去收集/C045个乌龟壳/C00。'),
  ('ov_hint.bin', 569, 26738691, '将收集的乌龟壳交给通玄先生，他又要你去收集/C045个蛾蛹黏液/C00。'),
  ('ov_hint.bin', 57, 1114113, '/C05桃源村容大胖子/C00请你将一对/C04玉镯/C00带给他的女儿/C05容容/C00，容大胖子家在村子的西南角。'),
  ('ov_hint.bin', 570, 26738692, '将收集的蛾蛹黏液交给通玄先生，他终于承认自己就是通玄先生，并且告诉你所缺的药材叫做七孔心。'),
  ('ov_hint.bin', 571, 26738693, '回到龙城，将药材告诉蓟子训，得知通玄先生便是转世人间的铁拐李大仙！'),
  ('ov_hint.bin', 572, 26804225, '受/C05蓟子训/C00之命，先去华山地宫/C04山鼠/C00身上收集/C04三根茱萸/C00，然后去见通玄先生。'),
  ('ov_hint.bin', 573, 26804226, '将三根茱萸交给通玄先生，终于唤醒了他沉睡的前世之魂。得到铁拐李的灵符，回去见蓟子训。'),
  ('ov_hint.bin', 574, 26804227, '蓟子训请你在机缘成熟的时候将灵符交给太上老君的使者。'),
  ('ov_hint.bin', 575, 26869761, '帮/C05村民包打听/C00去问问/C05木匠左异/C00，她家的凳子什么时候修好。'),
  ('ov_hint.bin', 576, 26869762, '去找/C05龙城名剑坊分店/C00，问问他木匠左异的锤子什么时候修好。'),
  ('ov_hint.bin', 577, 26869763, '拿到修好的锤子，回去找木匠左异。'),
  ('ov_hint.bin', 578, 26869764, '将锤子交给木匠左异，得到修好的凳子，拿回去给包打听。'),
  ('ov_hint.bin', 579, 26869765, '将凳子交给包打听，打听到一个骑驴老人的奇事。'),
  ('ov_hint.bin', 58, 1114114, '将玉镯交给容容，她请你把/C04外衣/C00交给容大胖子。'),
  ('ov_hint.bin', 580, 26935297, '去野外收集/C0415个鬼火/C00，以鬼火之力聚拢骑驴老人四散的魂魄。'),
  ('ov_hint.bin', 581, 27000833, '去夺回被/C04地藏小妖/C00吸走的骑驴老人的魂魄。需要一个用来装魂魄的/C04空瓶子/C00。'),
  ('ov_hint.bin', 582, 27066369, '去华山地宫收集/C0410个烛火/C00，用这些烛火照亮骑驴老人的回魂之路。'),
  ('ov_hint.bin', 583, 27131905, '将/C04元丹/C00放入骑驴老人即将回魂的肉身之中，骑驴老人的肉身此刻在/C05华山北麓/C00的一个茅屋前。'),
  ('ov_hint.bin', 584, 27197441, '龙城北郊的/C05麻姑/C00身患血疾，希望你帮她向龙城的/C05萼绿华/C00仙子求助。'),
  ('ov_hint.bin', 585, 27197442, '萼绿华告知麻姑的血疾需要/C04云母粉/C00方能救治，云母粉的下落可向城北的/C05广成子/C00打听。'),
  ('ov_hint.bin', 586, 27197443, '广成子指点你去桃源找/C05素女/C00，据说素女有一种/C04天花粉/C00可治疗血疾。'),
  ('ov_hint.bin', 587, 27197444, '素女请你帮助收集天花粉的合成材料：/C045个花瓣、10个泥块/C00。'),
  ('ov_hint.bin', 588, 27197445, '将收集的材料交给素女，得到天花粉。请将天花粉交给龙城的萼绿华。'),
  ('ov_hint.bin', 589, 27197446, '将天花粉交给萼绿华，原来天花粉正是云母粉，请你把云母粉给麻姑送去。'),
  ('ov_hint.bin', 59, 1114115, '将外衣交给容大胖子，任务完成。'),
  ('ov_hint.bin', 590, 27197447, '将云母粉送给麻姑，她十分感谢，并且决定从此潜心修道，任务完成。'),
  ('ov_hint.bin', 591, 27262977, '萼绿华开出一张奇怪的药方，要玩家交给桃源的/C04素女/C00。'),
  ('ov_hint.bin', 592, 27262978, '将药方交给素女，她用一首劝世歌破解了药方的秘密。'),
  ('ov_hint.bin', 593, 27328513, '前往桃源村，向/C05桃树仙/C00打听/C04仙桃/C00的下落。'),
  ('ov_hint.bin', 594, 27328514, '桃树仙告知，在/C05上古岳平原/C00一种叫做/C10夭夭/C00的小怪，身上会掉落桃子。'),
  ('ov_hint.bin', 595, 27328515, '得到一个桃子，回桃源村请桃树仙鉴别是否为/C04仙桃/C00。'),
  ('ov_hint.bin', 596, 27328516, '这只是一个普通的桃子，需要重新去寻找仙桃。'),
  ('ov_hint.bin', 597, 27328517, '找到仙桃，回龙城找/C05萼绿华/C00回复任务。'),
  ('ov_hint.bin', 598, 27328518, '萼绿华要你将仙桃送给/C05素女/C00。'),
  ('ov_hint.bin', 599, 27328519, '素女服下仙桃后，，终于去除心中迷障，回复了前世的记忆，任务完成。'),
  ('ov_hint.bin', 6, 262145, '帮/C05龙城店小二阿晃/C00收集/C0410枚蛇胆/C00。/C05华山/C00上的/C10碧蛇/C00会掉落蛇胆。'),
  ('ov_hint.bin', 60, 1179649, '桃源村/C05武器师匠哈骏/C00收购/C04墨石和青石/C00，在/C05缘溪走廊和听溪走廊/C00的/C10蚯蚓/C00身上会掉落这两种矿石。'),
  ('ov_hint.bin', 600, 27394049, '龙城镖师/C05孟歧/C00丢失了一本受人所托的兵书，帮他向/C04萼绿华仙子/C00寻求帮助。'),
  ('ov_hint.bin', 601, 27394050, '萼绿华推算出丢失兵书的去处，原来被/C04木头人/C00偷去了。夺回/C04兵书/C00。'),
  ('ov_hint.bin', 602, 27394051, '夺回被木头人偷去的兵书，按照萼绿华的指点，先将兵书拿给龙城的钟离门人/C05裴谌/C00看看。'),
  ('ov_hint.bin', 603, 27394052, '裴谌看过兵书后，将其归还给镖师孟歧。'),
  ('ov_hint.bin', 604, 27459585, '裴谌托你将一个/C04玉匣/C00交给阳泉平原的/C05权寂道/C00'),
  ('ov_hint.bin', 605, 27525121, '/C05权寂道/C00拜托玩家从龙城的/C05盗墓王疾风/C00手中要回/C04青藜芭蕉宝扇/C00。')
INSERT INTO "ov_named" ("tbl", "row_no", "ref_id", "name") VALUES
  ('ov_hint.bin', 606, 27525122, '盗墓王疾风告诉玩家，如果要拿回宝扇，除非把石晶变成金块。先去/C04华山地宫/C00里采集/C04石身人面怪/C00掉落的/C04石晶/C00。'),
  ('ov_hint.bin', 607, 27525123, '在华山地宫第2层打石身人面怪，得到/C04石晶/C00。传说钟离大仙有点石成金的本领，去找/C04权寂道/C00把！'),
  ('ov_hint.bin', 608, 27525124, '将石晶交给权寂道，他运用法术将石晶变成了金灿灿的金块！将金块拿去给龙城的/C05盗墓王疾风/C00。'),
  ('ov_hint.bin', 609, 27525125, '将金块交给盗墓王疾风，他却告诉玩家宝扇被/C04黄鹤遗址/C00里的/C04轮面怪/C00抢去了。'),
  ('ov_hint.bin', 61, 1179650, '将打到的矿石交给武器师匠哈骏，换取报酬，任务完成。'),
  ('ov_hint.bin', 610, 27525126, '在黄鹤遗址里打轮面怪，得到青藜芭蕉宝扇，现在可以去交给权寂道啦。'),
  ('ov_hint.bin', 611, 27525127, '权寂道得到宝扇，灵力全部回复，并送给你一张灵符，任务完成。'),
  ('ov_hint.bin', 612, 27590657, '找龙城/C05阿筝/C00取回借出的/C04铜壶/C00。'),
  ('ov_hint.bin', 613, 27590658, '帮助阿筝收集/C0410根灯芯/C00。'),
  ('ov_hint.bin', 614, 27590659, '将收集的灯芯送给阿筝，得到铜壶。'),
  ('ov_hint.bin', 615, 27590660, '将铜壶交给许栖岩，任务完成。'),
  ('ov_hint.bin', 616, 27656193, '接受龙城/C05许栖岩/嘱托，将一盆/C04白牡丹/C00交给观音院的/C04小和尚正中/C00。'),
  ('ov_hint.bin', 617, 27656194, '送出白牡丹，听说了关于山石怪人的故事，回去告诉许栖岩。'),
  ('ov_hint.bin', 618, 27656195, '将山石怪人的故事告诉许栖岩，在许栖岩的指点下，猜出“山石怪人”其实是一个岩字。任务完成。'),
  ('ov_hint.bin', 619, 27721729, '接受龙城/C05许栖岩/C00委托，前往/C04黄鹤遗址/C00寻找丢失的/C04画轴/C00。画轴可能是被/C04铁钳人/C00捡去了。'),
  ('ov_hint.bin', 62, 1245185, '帮桃源村的/C05哈大娘/C00买一个/C04肉片/C00，肉片在/C05道具商人清悠/C00处可以买到。'),
  ('ov_hint.bin', 620, 27721730, '在黄鹤遗址的铁钳人身上找到画轴，回去交给许牺岩。'),
  ('ov_hint.bin', 621, 27721731, '将画轴交给/C04飞鹤台/C00的/C04山石先生/C00，看他是否能够认出这幅画。'),
  ('ov_hint.bin', 622, 27721732, '画轴无法唤醒山石先生的回忆，回去向许牺岩复命。'),
  ('ov_hint.bin', 623, 27721733, '回到龙城向许栖岩复命，任务完成。'),
  ('ov_hint.bin', 624, 27787265, '龙城/C05歌姬骊姜/C00请你帮她采集缝制仙袍需要的宝珠：/C0410颗火灵珠/C00；/C0410颗地藏珠/C00和/C041颗石珠/C00。'),
  ('ov_hint.bin', 625, 27787266, '这些宝珠分别可以在/C04狐妖/C00、/C04地藏小妖/C00和华山地宫的/C04不动明王/C00身上得到。'),
  ('ov_hint.bin', 626, 27787267, '收集齐宝珠后交给歌姬骊姜，她请玩家将缝制好的/C04仙袍/C00送给暗恋的/C04许栖岩/C00，得知一只精美/C04花簪/C00。'),
  ('ov_hint.bin', 627, 27787268, '将仙袍交给许栖岩，得知花簪竟是当年吕洞宾的珍爱之物。许栖岩要你将花簪交给山石先生，如果他是吕洞宾，便一定会认识这只花簪！'),
  ('ov_hint.bin', 628, 27787269, '山石先生见到花簪后，前尘记忆全部被唤醒，原来他就是被贬下人间的吕洞宾。得到灵符，任务完成。'),
  ('ov_hint.bin', 629, 27852801, '受/C05老君使者/C00之命，前往瀛洲岛出云城，寻找哪吒三太子的转世－－/C05出云隐者/C00。'),
  ('ov_hint.bin', 63, 1245186, '买到肉片交给哈大娘，她需要/C0410个松子果/C00做松子饼。/C05芳草林东和芳草林西/C00的/C10闪电鼠/C00会掉落松子果。'),
  ('ov_hint.bin', 630, 27918337, '接受/C05出云隐者/C00的考验，收集/C04奇特的碎片、奇怪的碎片、奇异的碎片、神奇的碎片/C00各/C0410片/C00。'),
  ('ov_hint.bin', 631, 27918338, '四种碎片分别在/C04出云北郊和出云山道/C00的/C04黄鱼怪、蓝鱼怪、黑蜂、玄武兽/身上掉落。'),
  ('ov_hint.bin', 632, 27983873, '接受/C05出云隐者/C00的使命，从/C05大秦山原/C00的飞天猴子、大熊和苍狼皇身上找到/C04飞天翼、灵熊掌、狼皇头/C00。'),
  ('ov_hint.bin', 633, 27983874, '从飞天猴子身上得到飞天翼。'),
  ('ov_hint.bin', 634, 27983875, '从大熊身上得到灵熊掌。'),
  ('ov_hint.bin', 635, 27983876, '从苍狼皇身上得到狼皇头。'),
  ('ov_hint.bin', 636, 27983877, '将/C04飞天翼、灵熊掌、狼皇头/C00交给出云隐者，任务完成。'),
  ('ov_hint.bin', 637, 28049409, '接受/C05出云隐者/C00的使命，前往/C05出云之角/C00，消灭被魔气控制的/C10兔王/C00。'),
  ('ov_hint.bin', 638, 28049410, '杀死兔王，回出云城复命。'),
  ('ov_hint.bin', 639, 28114945, '帮助/C05青牛山西和青牛山南/C00的/C10鹿角面具和鹅翅面具/C00摆脱沉沦魔域之苦，从它们身上寻找/C04洁净的鹅翅之心和鹿角之心/C00。'),
  ('ov_hint.bin', 64, 1245187, '收集齐10个松子果，交给哈大娘，任务完成。'),
  ('ov_hint.bin', 640, 28114946, '得到洁净的鹅翅之心。'),
  ('ov_hint.bin', 641, 28114947, '得到洁净的鹿角之心。'),
  ('ov_hint.bin', 642, 28180481, '勇闯/C05修罗殿/C00，取回/C045个牛头的牛角/C00和/C045个马面的面具/C00作为勇气的凭证交给/C05出云隐者/C00。'),
  ('ov_hint.bin', 643, 28246017, '接受新使命，收伏/C05青牛山/C00的/C10魔王飞天猪/C00。'),
  ('ov_hint.bin', 644, 28246018, '收伏魔王飞天猪，将其魂魄收在收魂铁牌中，回去交给出云隐者。'),
  ('ov_hint.bin', 645, 28311553, '作为瀛洲使者，前往/C05蓬莱岛/C00，告知/C05太上老君/C00关于水魔珠发生的变故。'),
  ('ov_hint.bin', 646, 28377089, '帮助太上老君寻找压阵所需的三样法物之一——/C049根锁命绳/C00。锁命绳在/C05上天郊和后天郊/C00的/C10蜈蚣风筝/C00身上会找到。'),
  ('ov_hint.bin', 647, 28442625, '帮助太上老君寻找压阵所需的三样法物之二——/C046个转运锁/C00。转运锁在/C05瑶池台/C00的/C10天判官/C00身上会找到。'),
  ('ov_hint.bin', 648, 28508161, '帮助太上老君寻找压阵所需的最后一样法物——/C043个照劫镜/C00。照劫镜在/C05千年之镜/C00的/C10冰精灵/C00身上会找到。'),
  ('ov_hint.bin', 649, 28573697, '太上老君的演算之阵推算出水魔珠带来的将是盘古大神所预言的五千年之劫！太上老君请你将此消息告诉/C05玉皇大帝/C00。'),
  ('ov_hint.bin', 65, 1310721, '桃源村的/C05容大嫂/C00缝制新衣，需要/C0420片兔毛/C00。村北/C05芳草林/C00的/C10粉粉兔和绒绒兔/C00身上会掉兔毛。'),
  ('ov_hint.bin', 650, 28639233, '遵照太上老君的指点，前往/C05遗忘之角/C00，寻找一个自称/C05“风灵之祖”/C00的怪人。'),
  ('ov_hint.bin', 651, 28639234, '接受风灵之祖的挑战，打败/C0410个/C00/C10风精灵/C00和/C0410个/C00/C10风妖精/C00。'),
  ('ov_hint.bin', 652, 28639235, '风灵之祖已经完全不记得前尘旧事，看来只有回去找/C05太上老君/C00想办法。'),
  ('ov_hint.bin', 653, 28639236, '受命在天郊/C10火鸟/C00身上取得/C04火鸟胆/C00、在飞仙台/C10笔仙/C00身上取得/C04紫竹/C00，在/C10风精灵/C00身上取得风灵心。'),
  ('ov_hint.bin', 654, 28639237, '从火鸟身上得到火鸟胆。'),
  ('ov_hint.bin', 655, 28639238, '从笔仙身上达到紫竹。'),
  ('ov_hint.bin', 656, 28639239, '从风精灵身上风灵心。'),
  ('ov_hint.bin', 657, 28639240, '得到/C04紫竹玉萧/C00，在风灵之祖面前吹奏，若他真是韩湘子，一定会醒转过来。'),
  ('ov_hint.bin', 658, 28704769, '在/C05仙台东/C00找到/C05蓝衫乞丐/C00，这个贪吃的人要你给他/C043个叉烧包/C00。'),
  ('ov_hint.bin', 659, 28704770, '将叉烧包交给蓝衫乞丐后，他还要吃/C041只烤乳猪/C00。'),
  ('ov_hint.bin', 66, 1310722, '收集齐20片兔毛，交给容大嫂，任务完成。'),
  ('ov_hint.bin', 660, 28704771, '吃完烤乳猪，蓝衫乞丐又要你送他/C042瓶人参酒/C00。'),
  ('ov_hint.bin', 661, 28704772, '喝下人参酒后，蓝衫乞丐呼呼大睡过去，你决定找太上老君想想办法。'),
  ('ov_hint.bin', 662, 28704773, '原来蓝衫乞丐中了火焰岛上的贪食蛊，需用醒梦丹化解，炼制醒梦丹需要收集如下材料：'),
  ('ov_hint.bin', 663, 28704774, '火精灵的/C04赤心珠10颗/C00，雪精灵的/C04冰晶5片/C00，云中兽的/C04雾灵珠5个/C00和天翼魔的/C04天魔翼3个/C00。'),
  ('ov_hint.bin', 664, 28704775, '合成/C04醒梦丹/C00，拿去交给蓝衫乞丐。'),
  ('ov_hint.bin', 665, 29491201, '受龙城通天塔里的/C05老君使者/C00之托，与同伴组队潜入塔狱找出魔眼石。'),
  ('ov_hint.bin', 666, 29491202, '找到/C04“魔眼石”/C00，去交给塔狱外的老君使者吧！'),
  ('ov_hint.bin', 667, 29556737, '帮助/C05华山脚/C00的/C05墨玉/C00解救被封印在结界中的/C04冰凌的魂魄/C00，需要/C04五个职业/C00的玩家/C04组队/C00进入。'),
  ('ov_hint.bin', 668, 29556738, '进入第一层结界需要职业特定的/C04钥匙/C00，钥匙在/C10大蜗牛怪、碧蛇、山狼、小虎怪、小飞天猴子和灰狼/C00身上随机掉落。'),
  ('ov_hint.bin', 669, 29556739, '进入第一层结界后，五个职业的队员需要分别打开各职业的/C10结界封印/C00，才能打开第二层结界，召唤出/C10千年妖狐/C00。'),
  ('ov_hint.bin', 67, 1376257, '帮助桃源村的/C05壶公/C00教训咬伤他孙子的/C10小黑狗/C00。小黑狗常在/C05芳草林东和芳草林西/C00出没。'),
  ('ov_hint.bin', 670, 29556740, '成功打开五个/C10结界封印/C00，打开第二层结界，召唤出/C10千年妖狐/C00！'),
  ('ov_hint.bin', 671, 29556741, '打败千年妖狐，找到藏在狐妖躯壳内的冰凌的魂魄！返回华山脚，将冰凌的魂魄交给墨玉吧。'),
  ('ov_hint.bin', 672, 29622273, '去出云城北许愿树下找/C05青鸟仙子/C00，询问如何才能帮助/C05纯阳塔神卫/C00的女儿转生。'),
  ('ov_hint.bin', 673, 29622274, '用/C04琉石和璃石/C00制作的琉璃之心拥有使人转生的能力，将采集到的晶石交给/C04纯阳塔神卫/C00。'),
  ('ov_hint.bin', 674, 29622275, '集齐第一种晶石后，进入/C04纯阳塔/C00，找到塔里的/C10琉璃矿/C00，收集另一种晶石，同样也需要5颗。'),
  ('ov_hint.bin', 675, 29622276, '男玩家可在/C10苍狼皇/C00身上收集到/C045颗琉石/C00，女玩家可在/C10碧磷毒蛇/C00身上收集到/C045颗璃石/C00。'),
  ('ov_hint.bin', 676, 29687809, '杀死/C10愤恨的凶灵、彷徨的凶灵、悲戚的凶灵、嫉妒的凶灵、杀意的凶灵/C00，取到/C04喇摩、耶鞑、呜咽、泣血、天瀑/C00五颗宝石。'),
  ('ov_hint.bin', 677, 29687810, '用五颗宝石换取/C04天龙咒/C00，找到/C05封印之箱/C00，用咒语解开封印，取出/C04龙魂之刃/C00。'),
  ('ov_hint.bin', 678, 29687811, '成功取出/C04龙魂之刃/C00，交给/C04龙族遗臣/C00。'),
  ('ov_hint.bin', 679, 29753345, '接受/C05河上公/C00的使命，前往/C05天空之泉/C00寻找三种/C04镜之碎片/C00。'),
  ('ov_hint.bin', 68, 1376258, '教训小黑狗，将收集的/C04狗牙/C00交给壶公，领取报酬，任务完成。'),
  ('ov_hint.bin', 680, 29753346, '/C04镜之碎片-破/C00，藏在天泉第一层的怪物头目身上，只有在/C05剑客、药师或术士/C00的力量引导下才会出现。'),
  ('ov_hint.bin', 681, 29753347, '/C04镜之碎片-邪/C00，藏在天泉第二层的怪物头目身上，只有在/C05剑客、刺客或战士/C00的力量引导下才会出现。'),
  ('ov_hint.bin', 682, 29753348, '/C04镜之碎片-劫/C00，藏在天泉第三层的怪物头目身上，只有在/C05刺客、药师或术士/C00的力量引导下才会出现。'),
  ('ov_hint.bin', 683, 29753349, '此任务仅凭一人之力是难以完成的，和你的伙伴一起去找/C05二郎神杨戟/C00，他会送你去天空之泉。'),
  ('ov_hint.bin', 684, 29818881, '从天都/C05九天玄女/C00处得知，飞鸟和游鱼的故事与一段遗失的秘密有关，这个秘密被记载在一本遗失了的龙族典籍上。'),
  ('ov_hint.bin', 685, 29818882, '进入/C05天空之泉/C00，在/C10天泉鱼怪、天泉蟹怪和天泉虾怪/C00身上找到/C04五张典籍散页/C00。'),
  ('ov_hint.bin', 686, 29818883, '还缺少最后一页典籍，可能藏在天泉第三层的/C10变异魔龙/C00身上。消灭/C1030只鱼怪战士/C00后会召唤出变异魔龙。'),
  ('ov_hint.bin', 687, 29818884, '消灭30只鱼怪战士，召唤出变异魔龙！'),
  ('ov_hint.bin', 688, 29818885, '消灭变异魔龙，获得最后一页典籍！'),
  ('ov_hint.bin', 689, 29884417, '城主要将火种送个村民，你得到5个火种，将第一个火种送去给南城门最忠实的守卫。'),
  ('ov_hint.bin', 69, 1441793, '帮长乐村的纪宓送围巾给她的两个女儿/C04小叶/C00和/C04小溪/C00。'),
  ('ov_hint.bin', 690, 29884418, '将第二个火种送给城中失去女儿的伤心老人。'),
  ('ov_hint.bin', 691, 29884419, '将第三个火种送给城东北角那个怕事的年轻人。'),
  ('ov_hint.bin', 692, 29884420, '将第四个火种送给城中的小妹妹。'),
  ('ov_hint.bin', 693, 29884421, '将第五个火种送给城中的乞丐。'),
  ('ov_hint.bin', 694, 29884422, '火种已经全部送完，回去城主那交差吧，你会得到城主的祁福包。'),
  ('ov_hint.bin', 695, 29949953, '阿梅嫂要修葺房子，帮助她找齐材料。先到/C05工匠皓岩/C00那拿点木材。'),
  ('ov_hint.bin', 696, 29949954, '修葺房子还需要20个无泪东郊/C10魔异之石/C00身上的/C04刚石块/C00，还有到道具商人卿泓那拿到/C04麻绳/C00。')
INSERT INTO "ov_named" ("tbl", "row_no", "ref_id", "name") VALUES
  ('ov_hint.bin', 697, 29949955, '需要10朵芍药花，才能得到卿泓的麻绳。'),
  ('ov_hint.bin', 698, 29949956, '如果你已经得到20个刚石块，则收集完所有的建筑材料，回去交给阿梅嫂，你会得到阿梅嫂的祁福包。'),
  ('ov_hint.bin', 699, 30015489, '消灭无泪东郊和无泪南郊上10个/C10盾卫者/C00、15个/C10上古玄龟/C00、20个/C10石魈/C00，帮助罔祁剿灭城外的怪物。'),
  ('ov_hint.bin', 7, 262146, '将蛇胆交给店小二阿晃，得到/C04五坛蛇胆酒/C00，要分别送给/C05镖师孟歧、跑货商人南耘、木匠左异、矿工沙良和传令官莫贤/C00。'),
  ('ov_hint.bin', 70, 1441794, '将红色围巾交给小叶，但是她的围巾好像不是红色的。'),
  ('ov_hint.bin', 700, 30015490, '任务已经完成，怪物得到了震慑。可以回去罔祁那里复命了，你会得到罔祁的祁福包。'),
  ('ov_hint.bin', 701, 30081025, '从/C05无泪南郊/C00的/C10紫冥蝎/C00中找到投胎转生的神兽，不过要先到/C05无泪名剑坊分店/C00那要一把困兽环。'),
  ('ov_hint.bin', 702, 30081026, '需要10个/C04魔铁/C00与无泪名剑坊分店交换困兽环，魔铁在无泪东郊的/C10涂山妖民/C00身上可以得到。'),
  ('ov_hint.bin', 703, 30081027, '得到困兽环，接着去道具商人卿泓那要/C04一袋仙豆/C00，作为诱饵。'),
  ('ov_hint.bin', 704, 30081028, '仙豆和困兽环都已准备好，前往无泪南郊消灭/C10紫冥蝎/C00，一定概率重生出神兽。'),
  ('ov_hint.bin', 705, 30146561, '帮助长老寻找医书遗页，前往/C05无泪盆地/C00寻找线索，医书遗页应该就藏在无泪盆地的某处。'),
  ('ov_hint.bin', 706, 30146562, '耐心的等候/C05无泪东郊/C00的/C10神奇甲虫/C00的出现，打败它就能得到/C04赤虫壳/C00。'),
  ('ov_hint.bin', 707, 30212097, '帮助/C05莫须/C00唤醒他的记忆，找回他和札图之间的情谊。'),
  ('ov_hint.bin', 708, 30212098, '消灭无泪南郊上20个/C10妖蓝水姬/C00和20个/C10吞噬之气/C00，找回莫须的时间锦囊。'),
  ('ov_hint.bin', 709, 30212099, '莫须已经回忆起过去的友情，回去告诉札图这个好消息，你会得到代表友情的友情之星。'),
  ('ov_hint.bin', 71, 1441795, '原来红色围巾是小溪的，需要找小叶拿回红色围巾。'),
  ('ov_hint.bin', 710, 30277633, '去找敏克罗，替琉璃弄清楚他遗忘了爱情的原因。'),
  ('ov_hint.bin', 711, 30277634, '去无泪盆地消灭/C10魔念者/C00拿到红魔水和/C10持斧小鬼/C00拿到蓝魔水，清醒敏克罗模糊的记忆。'),
  ('ov_hint.bin', 712, 30277635, '敏克罗已经想起了失去的爱情，将这朵代表敏克罗心意的玫瑰带回给琉璃，你会得到代表爱情的爱情之星。'),
  ('ov_hint.bin', 713, 30343169, '到无泪盆地的天眼去寻找襄襄梦中的漂亮姐姐，打探襄襄爸爸的下落'),
  ('ov_hint.bin', 714, 30343170, '在无泪盆地的/C10青魔妖晶/C00身上取得醒梦风铃，再到幻幽平原一打败15个/C10丧气浊液/C00，解救襄襄爸爸。'),
  ('ov_hint.bin', 715, 30343171, '已消灭15只丧气浊液，快带着醒梦风铃去找襄襄爸爸，他就在幻幽平原一的某处。'),
  ('ov_hint.bin', 716, 30343172, '襄襄爸爸已经清醒，回去告诉襄襄这个好消息，你会得到代表亲情的亲情之星。'),
  ('ov_hint.bin', 717, 30408705, '在/C10赤血妖晶/C00那收集15个红血晶，在/C10青魔妖晶/C00那收集15个绿血晶，在幻幽平原一和无泪盆地上能找到它们的身影。'),
  ('ov_hint.bin', 718, 30408706, '将混色宝珠拿给楼兰的富商古鲁，让他卖个好价钱。'),
  ('ov_hint.bin', 719, 30408707, '混色宝珠已经安全送到楼兰，回去无泪城向无泪天道山分店交差，你会得到神奇的瓶子。'),
  ('ov_hint.bin', 72, 1441796, '从小叶那里换回红色围巾，请去交给小溪吧！'),
  ('ov_hint.bin', 720, 30474241, '为了得到天神甘露，必须打败出现在幻幽平原一的怪物/C10妖晶魔王/C00。'),
  ('ov_hint.bin', 721, 30474242, '已打败妖晶魔王，回去向天眼侍者复命。'),
  ('ov_hint.bin', 722, 30474243, '得到天神甘露，拿回去无泪城交给长老。'),
  ('ov_hint.bin', 723, 30539777, '去找阿桑，了解他做噩梦的原因。'),
  ('ov_hint.bin', 724, 30539778, '消灭无泪盆地上30个/C10持斧小鬼/C00和幻幽平原一上25个/C10灰翼鬼蝠/C00，替阿桑清除心魔。'),
  ('ov_hint.bin', 725, 30539779, '已经完成了任务，回去告诉阿桑这个好消息。'),
  ('ov_hint.bin', 726, 30539780, '解决了阿桑噩梦的根源，去向岳林交差吧。'),
  ('ov_hint.bin', 727, 30605313, '到幻幽平原一收集/C10紫羽腾蛇/C0015根羽毛，交给无泪天道山分店，用来完成香提的羽衣。其中会有意外收获哦！'),
  ('ov_hint.bin', 728, 30605314, '要完成羽衣还需要一些蚕丝，到客栈老板那要一些回来。'),
  ('ov_hint.bin', 729, 30605315, '得到蚕丝，拿回去给无泪天道山分店，就可以完成羽衣了。'),
  ('ov_hint.bin', 73, 1441797, '将黄色围巾交给小溪，但是她的围巾好像不是黄色的。'),
  ('ov_hint.bin', 730, 30605316, '终于完成了羽衣，赶紧拿回去给神女香提，交换红色补天神石。'),
  ('ov_hint.bin', 731, 30670849, '向/C05长老/C00打听一下客栈生意不好的原因。'),
  ('ov_hint.bin', 732, 30670850, '去无泪盆地消灭/C10通灵玄龟/C00，拿到稀有的/C04驱邪龟灵/C00，回去交给客栈老板。'),
  ('ov_hint.bin', 733, 30736385, '去找城门守卫/C05罔祁/C00，打听黑色和白色补天神石的下落。'),
  ('ov_hint.bin', 734, 30736386, '只要在幻幽平原二消灭个裂石魔和个行刺者，拿回太极石。回去交给神女香提。15/C10/C0020/C10/C00'),
  ('ov_hint.bin', 735, 30801921, '到/C05心岛神坛/C00那寻找阻碍岳林施法的人，此人法力高强。'),
  ('ov_hint.bin', 736, 30801922, '消灭幻幽平原二中强大的怪物/C10寒神/C00，为寻找曹仙人扫除威胁。'),
  ('ov_hint.bin', 737, 30801923, '已成功消灭了寒神，向神坛祭司风史报告这个消息。'),
  ('ov_hint.bin', 738, 30867457, '选择幻幽平原二、幻幽平原三或是镜湖北岸任意一个地方，消灭相应的怪物，你就会得到曹仙人的信息。'),
  ('ov_hint.bin', 739, 30867458, '消灭幻幽平原三上的20个/C10刚破鬼/C00，你就会得到关于曹仙人的提示。'),
  ('ov_hint.bin', 74, 1441798, '原来黄色围巾是小叶的，需要找小溪拿回黄色围巾。'),
  ('ov_hint.bin', 740, 30867459, '消灭镜湖北岸上的20个/C10灵斑蜥/C00，你就会得到关于曹仙人的提示。'),
  ('ov_hint.bin', 741, 30867460, '你猜错了！曹仙人并不在此处，回到岳林那重新选择其他的地点吧。'),
  ('ov_hint.bin', 742, 30867461, '你已成功解救出曹仙人的坐骑兔子小白，它就在幻幽平原三的某处，去找它吧。'),
  ('ov_hint.bin', 743, 30867462, '你猜错了！曹仙人并不在此处，回到岳林那重新选择其他的地点吧。'),
  ('ov_hint.bin', 744, 30932993, '快去找神女香提，询问拯救兔子小白的方法。'),
  ('ov_hint.bin', 745, 30932994, '到镜湖北岸的/C10剧毒鬼蝎/C00身上取得蝎毒，拿回去救兔子小白。'),
  ('ov_hint.bin', 746, 30998529, '到幻幽平原四消灭20个/C10矛卫者/C00和20个/C10抛石小鬼/C00，寻找曹仙人的信息。'),
  ('ov_hint.bin', 747, 32833537, '去邀请富商藤老爷 、客栈老板卢广、盗墓王疾风同乐新春，并请舞姬月影、歌姬骊姜来助兴'),
  ('ov_hint.bin', 748, 32833538, '回见镖师孟歧'),
  ('ov_hint.bin', 749, 32899073, '去跑货商人南耘那里购买年货'),
  ('ov_hint.bin', 75, 1441799, '从小溪那里换回黄色围巾，请去交给小叶吧！'),
  ('ov_hint.bin', 750, 32899074, '自行收集年货交给妞妞妈'),
  ('ov_hint.bin', 751, 32899075, '通知云翘给妞妞妈留个位置'),
  ('ov_hint.bin', 752, 32899076, '回见妞妞妈'),
  ('ov_hint.bin', 753, 32964609, '去广成子那里索要“饭团”、道具商人铃铛 处索要“糕饼”各20块'),
  ('ov_hint.bin', 754, 32964610, '拿着索要回来的物品，交给小和尚正中'),
  ('ov_hint.bin', 755, 33030145, '通知小松准备送羊头到藤老爷'),
  ('ov_hint.bin', 756, 33030146, '回见藤老爷'),
  ('ov_hint.bin', 757, 33030147, '去准备“锦鲤”、“银鲤”、“金红鲤”、“青龙鲤”每样各1条给藤老爷'),
  ('ov_hint.bin', 758, 33030148, '将四色鲤鱼供奉给财神'),
  ('ov_hint.bin', 759, 33030149, '回见藤老爷'),
  ('ov_hint.bin', 76, 1441800, '将换回的红色围巾交给小溪以后，回去找纪宓吧！'),
  ('ov_hint.bin', 760, 33095681, '找治疗师妙仙子询问病情'),
  ('ov_hint.bin', 761, 33095682, '去龙城的巧匠左慈那里寻找“鞭炮”缓解病情'),
  ('ov_hint.bin', 762, 33095683, '去矿工沙良那里寻找“硫磺”和“硝土”'),
  ('ov_hint.bin', 763, 33095684, '回见左慈'),
  ('ov_hint.bin', 764, 33095685, '将做好的鞭炮带给病叟'),
  ('ov_hint.bin', 765, 33161217, '帮助新年娃娃在/C04吟松谷西/C00找回/C05胡罗卜娃娃/C00。'),
  ('ov_hint.bin', 766, 33161218, '拿着被咬过的胡萝卜找新年娃娃领取奖励。'),
  ('ov_hint.bin', 767, 33226753, '在/C0424/C00小时内能把神牛分身练到80级满级。'),
  ('ov_hint.bin', 768, 33292289, '大年初一，/C05新年娃娃/C00请你去向龙城的/C05巧匠左慈/C00姐姐询问制作/C04爆竹/C00的配方。'),
  ('ov_hint.bin', 769, 33292290, '制造爆竹需要/C04导火线、火药和红纸/C00，巧匠左慈建议你去找/C05矿工沙良/C00，他或许有/C04火药/C00。'),
  ('ov_hint.bin', 77, 1441801, '将换回的黄色围巾交给小叶以后，回去找纪宓吧！'),
  ('ov_hint.bin', 770, 33292291, '得到制作爆竹的火药，还缺少/C04导火线和和红纸/C00，矿工沙良告诉你/C05跑货商人南耘/C00那里也许有。'),
  ('ov_hint.bin', 771, 33292292, '/C05跑货商人南耘/C00将红纸送给了你，并建议用/C04棉线/C00代替导火线，/C05妞妞妈/C00专门做针线活的，应该有棉线。'),
  ('ov_hint.bin', 772, 33292293, '从/C05妞妞妈/C00处得到棉线，回去交给/C05新年娃娃/C00吧。'),
  ('ov_hint.bin', 773, 33357825, '大年初二，帮新年娃娃收集至少/C048张春联碎片/C00，龙城野外/C10绒绒兔、甲虫、蛾蛹怪和绿蛙兵/C00身上可能有。'),
  ('ov_hint.bin', 774, 33423361, '大年初四吃饺子，去/C05桃源村/C00找/C05容大嫂/C00，为新年娃娃带回香喷喷的新年/C04饺子/C00。'),
  ('ov_hint.bin', 775, 33423362, '容大嫂的饺子还缺少饺子馅，去/C05龙城东郊/C00找/C05猎人伯山甫/C00，取回新鲜的/C04猪肉/C00。'),
  ('ov_hint.bin', 776, 33423363, '在/C05猎人伯山甫/C00处得到新鲜的/C04猪肉/C00，会桃源村交给/C05容大嫂/C00。'),
  ('ov_hint.bin', 777, 33423364, '香喷喷的饺子做好啦，快去给龙城的新年娃娃送去吧！'),
  ('ov_hint.bin', 778, 33488897, '在/C10步行鸟、蚯蚓、树妖、桃树妖、灯怪、夭夭、地藏小妖/C00身上找回散落的/C048个财神的红包/C00，到新年娃娃处兑换压岁钱。'),
  ('ov_hint.bin', 779, 33554433, '大年初三，帮新年娃娃给/C05桃源村的壶公、哈大娘，长乐村的茶姥/C00送/C04请柬/C00，邀请他们参加龙城蟠桃宴。'),
  ('ov_hint.bin', 78, 1507329, '帮长乐村的/C05小溪/C00收集/C04蝴蝶的翅膀/C00。'),
  ('ov_hint.bin', 780, 33554434, '将请柬送给桃源村的壶公。'),
  ('ov_hint.bin', 781, 33554435, '将请柬送给桃源村的哈大娘。'),
  ('ov_hint.bin', 782, 33554436, '将请柬送给长乐村的茶姥。'),
  ('ov_hint.bin', 783, 33619969, '大年初七捉迷藏，在龙城四郊寻找新年娃娃的/C05八个替身娃娃/C00，每个替身娃娃都会对应一句新年的魔力祝福。'),
  ('ov_hint.bin', 784, 33619970, '/C05替身娃娃新年快乐/C00祝您新的一年吉祥顺心！'),
  ('ov_hint.bin', 785, 33619971, '/C05替身娃娃万事如意/C00祝您新的一年万事如意！'),
  ('ov_hint.bin', 786, 33619972, '/C05替身娃娃身体健康/C00祝您新的一年身体健康！')
INSERT INTO "ov_named" ("tbl", "row_no", "ref_id", "name") VALUES
  ('ov_hint.bin', 787, 33619973, '/C05替身娃娃学习顺利/C00祝您新的一年学习顺利！'),
  ('ov_hint.bin', 788, 33619974, '/C05替身娃娃恭喜发财/C00祝您新的一年恭喜发财！'),
  ('ov_hint.bin', 789, 33619975, '/C05替身娃娃好运连连/C00祝您新的一年好运连连！'),
  ('ov_hint.bin', 79, 1572865, '帮长乐村的/C05小叶/C00收集/C0420个蜗牛壳/C00做蜗壳笛，村南/C05吟松谷/C00里的/C10小蜗牛怪/C00会掉蜗牛壳。'),
  ('ov_hint.bin', 790, 33619976, '/C05替身娃娃爱情甜蜜/C00祝您新的一年爱情甜蜜！'),
  ('ov_hint.bin', 791, 33619977, '/C05替身娃娃事业有成/C00祝您新的一年事业有成！'),
  ('ov_hint.bin', 792, 33685505, '/C04副本规则：/C00'),
  ('ov_hint.bin', 793, 33685506, '1.进入副本后，玩家会自动获得15个“护卫召唤令”，护卫召唤令可以在NPC天神考验将军处召唤护卫助阵或者升级护卫。'),
  ('ov_hint.bin', 794, 33685507, '2.每隔一段时间副本内会出现各种怪物，玩家必须击败所有的怪物并保护结界石不被怪物破坏.'),
  ('ov_hint.bin', 795, 33685508, '3.如果死亡，玩家可以用彩玉进行复活（替身娃娃不能使用），等待20秒无复活的自动退出副本.'),
  ('ov_hint.bin', 796, 33685509, '4.天神大考验中除了药师的治愈术能对护卫使用外，玩家其余技能都不能对护卫使用。'),
  ('ov_hint.bin', 797, 33685510, '/C04胜利条件：/C00'),
  ('ov_hint.bin', 798, 33685511, '撑过50关，消灭所有怪物'),
  ('ov_hint.bin', 799, 33685512, '/C04失败条件：/C00'),
  ('ov_hint.bin', 8, 262147, '将蛇胆酒送给镖师孟歧。'),
  ('ov_hint.bin', 80, 1638401, '长乐村的/C05纪宓/C00请你帮忙找村里的/C05跑货商人药衡/C00看看有没有/C04竹条/C00。'),
  ('ov_hint.bin', 800, 33685513, '以下4个条件满足之一，即为失败：'),
  ('ov_hint.bin', 801, 33685514, '1.结界石被破坏'),
  ('ov_hint.bin', 802, 33685515, '2.玩家死亡后退出战场'),
  ('ov_hint.bin', 803, 33685516, '3.超过规定时间未消灭所有怪物.'),
  ('ov_hint.bin', 804, 33685517, '4.地图上怪物数量超过一定上限。'),
  ('ov_hint.bin', 805, 33685518, '/C04退出战场：/C00'),
  ('ov_hint.bin', 806, 33685519, '退出队伍、离开游戏，都判断为退出战场，挑战失败，只记录当前挑战批数。'),
  ('ov_hint.bin', 807, 33685520, '/C04副本难度：/C00'),
  ('ov_hint.bin', 808, 33685521, '目前只开放了“普通”难度级别，系统将按照玩家等级产生相应级别难度的怪物.'),
